type SeriesSetFormatter func(series storage.SeriesSet) error

func dumpSamples(ctx context.Context, path string, mint, maxt int64, match []string, formatter SeriesSetFormatter) (err error) {
	db, err := tsdb.OpenDBReadOnly(path, nil)
	if err != nil {
		return err
	}
	defer func() {
		err = tsdb_errors.NewMulti(err, db.Close()).Err()
	}()
	q, err := db.Querier(mint, maxt)
	if err != nil {
		return err
	}
	defer q.Close()

	matcherSets, err := parser.ParseMetricSelectors(match)
	if err != nil {
		return err
	}

	var ss storage.SeriesSet
	if len(matcherSets) > 1 {
		var sets []storage.SeriesSet
		for _, mset := range matcherSets {
			sets = append(sets, q.Select(ctx, true, nil, mset...))
		}
		ss = storage.NewMergeSeriesSet(sets, storage.ChainedSeriesMerge)
	} else {
		ss = q.Select(ctx, false, nil, matcherSets[0]...)
	}

	err = formatter(ss)
	if err != nil {
		return err
	}

	if ws := ss.Warnings(); len(ws) > 0 {
		return tsdb_errors.NewMulti(ws.AsErrors()...).Err()
	}

	if ss.Err() != nil {
		return ss.Err()
	}
	return nil
}

func formatSeriesSet(ss storage.SeriesSet) error {
	for ss.Next() {
		series := ss.At()
		lbs := series.Labels()
		it := series.Iterator(nil)
		for it.Next() == chunkenc.ValFloat {
			ts, val := it.At()
			fmt.Printf("%s %g %d\n", lbs, val, ts)
		}
		for it.Next() == chunkenc.ValFloatHistogram {
			ts, fh := it.AtFloatHistogram(nil)
			fmt.Printf("%s %s %d\n", lbs, fh.String(), ts)
		}
		for it.Next() == chunkenc.ValHistogram {
			ts, h := it.AtHistogram(nil)
			fmt.Printf("%s %s %d\n", lbs, h.String(), ts)
		}
		if it.Err() != nil {
			return ss.Err()
		}
	}
	return nil
}

// CondensedString is labels.Labels.String() without spaces after the commas.
func CondensedString(ls labels.Labels) string {
	var b bytes.Buffer

	b.WriteByte('{')
	i := 0
	ls.Range(func(l labels.Label) {
		if i > 0 {
			b.WriteByte(',')
		}
		b.WriteString(l.Name)
		b.WriteByte('=')
		b.WriteString(strconv.Quote(l.Value))
		i++
	})
	b.WriteByte('}')
	return b.String()
}

func formatSeriesSetOpenMetrics(ss storage.SeriesSet) error {
	for ss.Next() {
		series := ss.At()
		lbs := series.Labels()
		metricName := lbs.Get(labels.MetricName)
		lbs = lbs.DropMetricName()
		it := series.Iterator(nil)
		for it.Next() == chunkenc.ValFloat {
			ts, val := it.At()
			fmt.Printf("%s%s %g %.3f\n", metricName, CondensedString(lbs), val, float64(ts)/1000)
		}
		if it.Err() != nil {
			return ss.Err()
		}
	}
	fmt.Println("# EOF")
	return nil
}

func checkErr(err error) int {
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		return 1
	}
	return 0
}

	if mat.ContainsSameLabelset() {
		ev.errorf("vector cannot contain metrics with the same labelset")
	}

	return mat, warnings

case *parser.ParenExpr:
	return ev.eval(e.Expr)

case *parser.UnaryExpr:
	val, ws := ev.eval(e.Expr)
	mat := val.(Matrix)
	if e.Op == parser.SUB {
		for i := range mat {
			mat[i].Metric = mat[i].Metric.DropMetricName()
			for j := range mat[i].Floats {
				mat[i].Floats[j].F = -mat[i].Floats[j].F
			}
		}
		if mat.ContainsSameLabelset() {
			ev.errorf("vector cannot contain metrics with the same labelset")
		}
	}
	return mat, ws

case *parser.BinaryExpr:
	switch lt, rt := e.LHS.Type(), e.RHS.Type(); {
	case lt == parser.ValueTypeScalar && rt == parser.ValueTypeScalar:
		return ev.rangeEval(nil, func(v []parser.Value, _ [][]EvalSeriesHelper, enh *EvalNodeHelper) (Vector, annotations.Annotations) {
			val := scalarBinop(e.Op, v[0].(Vector)[0].F, v[1].(Vector)[0].F)
			return append(enh.Out, Sample{F: val}), nil
		}, e.LHS, e.RHS)
	case lt == parser.ValueTypeVector && rt == parser.ValueTypeVector:
		// Function to compute the join signature for each series.
		buf := make([]byte, 0, 1024)
		sigf := signatureFunc(e.VectorMatching.On, buf, e.VectorMatching.MatchingLabels...)
		initSignatures := func(series labels.Labels, h *EvalSeriesHelper) {
			h.signature = sigf(series)
		}
		switch e.Op {
		case parser.LAND:
			return ev.rangeEval(initSignatures, func(v []parser.Value, sh [][]EvalSeriesHelper, enh *EvalNodeHelper) (Vector, annotations.Annotations) {
				return ev.VectorAnd(v[0].(Vector), v[1].(Vector), e.VectorMatching, sh[0], sh[1], enh), nil
			}, e.LHS, e.RHS)
		case parser.LOR:
			return ev.rangeEval(initSignatures, func(v []parser.Value, sh [][]EvalSeriesHelper, enh *EvalNodeHelper) (Vector, annotations.Annotations) {
				return ev.VectorOr(v[0].(Vector), v[1].(Vector), e.VectorMatching, sh[0], sh[1], enh), nil
			}, e.LHS, e.RHS)
		case parser.LUNLESS:
			return ev.rangeEval(initSignatures, func(v []parser.Value, sh [][]EvalSeriesHelper, enh *EvalNodeHelper) (Vector, annotations.Annotations) {
				return ev.VectorUnless(v[0].(Vector), v[1].(Vector), e.VectorMatching, sh[0], sh[1], enh), nil
			}, e.LHS, e.RHS)
		default:
			return ev.rangeEval(initSignatures, func(v []parser.Value, sh [][]EvalSeriesHelper, enh *EvalNodeHelper) (Vector, annotations.Annotations) {
				return ev.VectorBinop(e.Op, v[0].(Vector), v[1].(Vector), e.VectorMatching, e.ReturnBool, sh[0], sh[1], enh), nil
			}, e.LHS, e.RHS)
		}

	case lt == parser.ValueTypeVector && rt == parser.ValueTypeScalar:
		return ev.rangeEval(nil, func(v []parser.Value, _ [][]EvalSeriesHelper, enh *EvalNodeHelper) (Vector, annotations.Annotations) {
			return ev.VectorscalarBinop(e.Op, v[0].(Vector), Scalar{V: v[1].(Vector)[0].F}, false, e.ReturnBool, enh), nil
		}, e.LHS, e.RHS)

	case lt == parser.ValueTypeScalar && rt == parser.ValueTypeVector:
		return ev.rangeEval(nil, func(v []parser.Value, _ [][]EvalSeriesHelper, enh *EvalNodeHelper) (Vector, annotations.Annotations) {
			return ev.VectorscalarBinop(e.Op, v[1].(Vector), Scalar{V: v[0].(Vector)[0].F}, true, e.ReturnBool, enh), nil
		}, e.LHS, e.RHS)
	}

case *parser.NumberLiteral:
	return ev.rangeEval(nil, func(v []parser.Value, _ [][]EvalSeriesHelper, enh *EvalNodeHelper) (Vector, annotations.Annotations) {
		return append(enh.Out, Sample{F: e.Val, Metric: labels.EmptyLabels()}), nil
	})

case *parser.StringLiteral:
	return String{V: e.Val, T: ev.startTimestamp}, nil

case *parser.VectorSelector:
	ws, err := checkAndExpandSeriesSet(ev.ctx, e)

impl Stack {
    /// Create a new stack.
    ///
    /// stdout and stderr will be set to [`OutDest::Inherit`]. So, if the last command is an external command,
    /// then its output will be forwarded to the terminal/stdio streams.
    ///
    /// Use [`Stack::capture`] afterwards if you need to evaluate an expression to a [`Value`](crate::Value)
    /// (as opposed to a [`PipelineData`](crate::PipelineData)).
    pub fn new() -> Self {
        Self {
            vars: Vec::new(),
            env_vars: Vec::new(),
            env_hidden: HashMap::new(),
            active_overlays: vec![DEFAULT_OVERLAY_NAME.to_string()],
            recursion_count: 0,
            parent_stack: None,
            parent_deletions: vec![],
            out_dest: StackOutDest::new(),
        }
    }

    /// Create a new child stack from a parent.
    ///
    /// Changes from this child can be merged back into the parent with
    /// [`Stack::with_changes_from_child`]
    pub fn with_parent(parent: Arc<Stack>) -> Stack {
        Stack {
            // here we are still cloning environment variable-related information
            env_vars: parent.env_vars.clone(),
            env_hidden: parent.env_hidden.clone(),
            active_overlays: parent.active_overlays.clone(),
            recursion_count: parent.recursion_count,
            vars: vec![],
            parent_deletions: vec![],
            out_dest: parent.out_dest.clone(),
            parent_stack: Some(parent),
        }
    }

    /// Take an [`Arc`] parent, and a child, and apply all the changes from a child back to the parent.
    ///
    /// Here it is assumed that `child` was created by a call to [`Stack::with_parent`] with `parent`.
    ///
    /// For this to be performant and not clone `parent`, `child` should be the only other
    /// referencer of `parent`.
    pub fn with_changes_from_child(parent: Arc<Stack>, child: Stack) -> Stack {
        // we're going to drop the link to the parent stack on our new stack
        // so that we can unwrap the Arc as a unique reference
        drop(child.parent_stack);
        let mut unique_stack = Arc::unwrap_or_clone(parent);

        unique_stack
            .vars
            .retain(|(var, _)| !child.parent_deletions.contains(var));
        for (var, value) in child.vars {
            unique_stack.add_var(var, value);
        }
        unique_stack.env_vars = child.env_vars;
        unique_stack.env_hidden = child.env_hidden;
        unique_stack.active_overlays = child.active_overlays;
        unique_stack
    }

    pub fn with_env(
        &mut self,
        env_vars: &[EnvVars],
        env_hidden: &HashMap<String, HashSet<String>>,
    ) {
        // Do not clone the environment if it hasn't changed
        if self.env_vars.iter().any(|scope| !scope.is_empty()) {
            env_vars.clone_into(&mut self.env_vars);
        }

        if !self.env_hidden.is_empty() {
            self.env_hidden.clone_from(env_hidden);
        }
    }

    /// Lookup a variable, returning None if it is not present
    fn lookup_var(&self, var_id: VarId) -> Option<Value> {
        for (id, val) in &self.vars {
            if var_id == *id {
                return Some(val.clone());
            }
        }

        if let Some(stack) = &self.parent_stack {
            if !self.parent_deletions.contains(&var_id) {
                return stack.lookup_var(var_id);
            }
        }
        None
    }

pub fn create_process(
    &self,
    stdin: Stdio,
    use_cmd: bool,
    span: Span,
) -> Result<(CommandSys, Option<PipeReader>), ShellError> {
    let mut process = if let Some(d) = self.env_vars.get("PWD") {
        let mut process = if use_cmd {
            self.spawn_cmd_command(d)
        } else {
            self.create_command(d)?
        };

        // do not try to set current directory if cwd does not exist
        if Path::new(&d).exists() {
            process.current_dir(d);
        }
        process
    } else {
        return Err(ShellError::GenericError{
            error: "Current directory not found".into(),
            msg: "did not find PWD environment variable".into(),
            span: Some(span),
            help: Some(concat!(
                "The environment variable 'PWD' was not found. ",
                "It is required to define the current directory when running an external command."
            ).into()),
            inner:Vec::new(),
        });
    };

    process.envs(&self.env_vars);

    // If the external is not the last command, its output will get piped
    // either as a string or binary
    let reader = if matches!(self.out, OutDest::Pipe) && matches!(self.err, OutDest::Pipe) {
        let (reader, writer) = os_pipe::pipe()?;
        let writer_clone = writer.try_clone()?;
        process.stdout(writer);
        process.stderr(writer_clone);
        Some(reader)
    } else {
        process.stdout(Stdio::try_from(&self.out)?);
        process.stderr(Stdio::try_from(&self.err)?);
        None
    };

    process.stdin(stdin);

    Ok((process, reader))
}

fn create_command(&self, cwd: &str) -> Result<CommandSys, ShellError> {
    // in all the other cases shell out
    if cfg!(windows) {
        //TODO. This should be modifiable from the config file.
        // We could give the option to call from powershell
        // for minimal builds cwd is unused
        if self.name.item.ends_with(".cmd") || self.name.item.ends_with(".bat") {
            Ok(self.spawn_cmd_command(cwd))
        } else {
            self.spawn_simple_command(cwd)
        }
    } else {
        self.spawn_simple_command(cwd)
    }
}

/// Spawn a command without shelling out to an external shell
pub fn spawn_simple_command(&self, cwd: &str) -> Result<std::process::Command, ShellError> {
    let (head, _, _) = trim_enclosing_quotes(&self.name.item);
    let head = nu_path::expand_to_real_path(head)
        .to_string_lossy()
        .to_string();

    let mut process = std::process::Command::new(head);

    for (arg, arg_keep_raw) in self.args.iter().zip(self.arg_keep_raw.iter()) {
        trim_expand_and_apply_arg(&mut process, arg, arg_keep_raw, cwd);
    }

    Ok(process)
}

