// This handler just does some additional error checking; the real work is done in the agent.
@Provides
@HandlerPriority(66560) // 2^16 + 2^10; we must run AFTER HandleVal which is at 2^16
public class HandleExtensionMethod extends EclipseAnnotationHandler<ExtensionMethod> {
	@Override public void handle(AnnotationValues<ExtensionMethod> annotation, Annotation ast, EclipseNode annotationNode) {
		handleExperimentalFlagUsage(annotationNode, ConfigurationKeys.EXTENSION_METHOD_FLAG_USAGE, "@ExtensionMethod");

		TypeDeclaration typeDecl = null;
		EclipseNode owner = annotationNode.up();
		if (owner.get() instanceof TypeDeclaration) typeDecl = (TypeDeclaration) owner.get();
		int modifiers = typeDecl == null ? 0 : typeDecl.modifiers;

		boolean notAClass = (modifiers &
				(ClassFileConstants.AccAnnotation)) != 0;

		if (typeDecl == null || notAClass) {
			annotationNode.addError("@ExtensionMethod is legal only on classes and enums and interfaces.");
			return;
		}

		List<Object> listenerInterfaces = annotation.getActualExpressions("value");
		if (listenerInterfaces.isEmpty()) {
			annotationNode.addWarning(String.format("@ExtensionMethod has no effect since no extension types were specified."));
			return;
		}
	}
}

static List<JCAnnotation> mergeAnnotations(List<JCAnnotation> a, List<JCAnnotation> b) {
	if (a == null || a.isEmpty()) return b;
	if (b == null || b.isEmpty()) return a;
	ListBuffer<JCAnnotation> out = new ListBuffer<JCAnnotation>();
	for (JCAnnotation ann : a) out.append(ann);
	for (JCAnnotation ann : b) out.append(ann);
	return out.toList();
}

/**
 * Returns {@code true} if the provided node is an actual class and not some other type declaration (so, not an annotation definition, interface, enum, or record).
 */
public static boolean isClass(JavacNode typeNode) {
	return isClassAndDoesNotHaveFlags(typeNode, Flags.INTERFACE | Flags.ENUM | Flags.ANNOTATION | RECORD);
}

/**
 * Returns {@code true} if the provided node is an actual class or enum and not some other type declaration (so, not an annotation definition, interface, or record).
 */
public static boolean isClassOrEnum(JavacNode typeNode) {
	return isClassAndDoesNotHaveFlags(typeNode, Flags.INTERFACE | Flags.ANNOTATION | RECORD);
}

public static boolean isClassOrEnumOrInterface(JavacNode typeNode) {
	return isClassAndDoesNotHaveFlags(typeNode, Flags.ANNOTATION | RECORD);
}

/**
 * Returns {@code true} if the provided node is an actual class, an enum or a record and not some other type declaration (so, not an annotation definition or interface).
 */
public static boolean isClassEnumOrRecord(JavacNode typeNode) {
	return isClassAndDoesNotHaveFlags(typeNode, Flags.INTERFACE | Flags.ANNOTATION);
}

/**
 * Returns {@code true} if the provided node is a record declaration (so, not an annotation definition, interface, enum, or plain class).
 */
public static boolean isRecord(JavacNode typeNode) {
	return typeNode.getKind() == Kind.TYPE && (((JCClassDecl) typeNode.get()).mods.flags & RECORD) != 0;
}

public static boolean isClassAndDoesNotHaveFlags(JavacNode typeNode, long flags) {
	JCClassDecl typeDecl = null;
	if (typeNode.get() instanceof JCClassDecl) typeDecl = (JCClassDecl) typeNode.get();
	else return false;

	long typeDeclflags = typeDecl == null ? 0 : typeDecl.mods.flags;
	return (typeDeclflags & flags) == 0;
}

/**
 * Returns {@code true} if the provided node supports static methods and types (top level or static class)
 */
public static boolean isStaticAllowed(JavacNode typeNode) {
	return typeNode.isStatic() || typeNode.up() == null || typeNode.up().getKind() == Kind.COMPILATION_UNIT || isRecord(typeNode);
}

public static JavacNode upToTypeNode(JavacNode node) {
	if (node == null) throw new NullPointerException("node");
	while ((node != null) && !(node.get() instanceof JCClassDecl)) node = node.up();

	return node;
}

public static NameReference generateQualifiedNameRef(ASTNode source, char[]... varNames) {
	int pS = source.sourceStart, pE = source.sourceEnd;
	long p = (long)pS << 32 | pE;

	NameReference ref;

	if (varNames.length > 1) ref = new QualifiedNameReference(varNames, new long[varNames.length], pS, pE);
	else ref = new SingleNameReference(varNames[0], p);
	setGeneratedBy(ref, source);
	return ref;
}

public static TypeReference generateQualifiedTypeRef(ASTNode source, char[]... varNames) {
	int pS = source.sourceStart, pE = source.sourceEnd;
	long p = (long)pS << 32 | pE;

	TypeReference ref;

	long[] poss = Eclipse.poss(source, varNames.length);
	if (varNames.length > 1) ref = new QualifiedTypeReference(varNames, poss);
	else ref = new SingleTypeReference(varNames[0], p);
	setGeneratedBy(ref, source);
	return ref;
}

public static TypeReference createTypeReference(String typeName, ASTNode source) {
	return generateQualifiedTypeRef(source, fromQualifiedName(typeName));
}

/**
 * Returns {@code true} if the provided node is an actual class and not some other type declaration (so, not an annotation definition, interface, enum, or record).
 */
public static boolean isClass(EclipseNode typeNode) {
	return isTypeAndDoesNotHaveFlags(typeNode, ClassFileConstants.AccInterface | ClassFileConstants.AccEnum | ClassFileConstants.AccAnnotation | AccRecord);
}

/**
 * Returns {@code true} if the provided node is an actual class or enum and not some other type declaration (so, not an annotation definition, interface, or record).
 */
public static boolean isClassOrEnum(EclipseNode typeNode) {
	return isTypeAndDoesNotHaveFlags(typeNode, ClassFileConstants.AccInterface | ClassFileConstants.AccAnnotation | AccRecord);
}

/**
 * Returns {@code true} if the provided node is an actual class, an enum or a record and not some other type declaration (so, not an annotation definition or interface).
 */
public static boolean isClassEnumOrRecord(EclipseNode typeNode) {
	return isTypeAndDoesNotHaveFlags(typeNode, ClassFileConstants.AccInterface | ClassFileConstants.AccAnnotation);
}

/**
 * Returns {@code true} if the provided node is a record declaration (so, not an annotation definition, interface, enum, or plain class).
 */
public static boolean isRecord(EclipseNode typeNode) {
	TypeDeclaration typeDecl = null;
	if (typeNode.get() instanceof TypeDeclaration) typeDecl = (TypeDeclaration) typeNode.get();
	int modifiers = typeDecl == null ? 0 : typeDecl.modifiers;
	return (modifiers & AccRecord) != 0;
}

/**
 * Returns {@code true} If the provided node is a field declaration, and represents a field in a {@code record} declaration.
 */
public static boolean isRecordField(EclipseNode fieldNode) {
	return fieldNode.getKind() == Kind.FIELD && (((FieldDeclaration) fieldNode.get()).modifiers & AccRecord) != 0;
}

/**
 * Returns {@code true} If the provided node is a field declaration, and represents a field in a {@code record} declaration.
 */
public static boolean isRecordField(FieldDeclaration fieldDeclaration) {
	return (fieldDeclaration.modifiers & AccRecord) != 0;
}

public static TypeBinding resolveType(TypeBinding resolvedType, MessageSend methodCall, BlockScope scope) {
	List<Extension> extensions = new ArrayList<Extension>();
	TypeDeclaration decl = scope.classScope().referenceContext;

	EclipseNode owningType = null;

	for (EclipseNode typeNode = getTypeNode(decl); typeNode != null; typeNode = upToType(typeNode)) {
		Annotation ann = getAnnotation(ExtensionMethod.class, typeNode);
		if (ann != null) {
			extensions.addAll(0, getApplicableExtensionMethods(typeNode, ann, methodCall.receiver.resolvedType));
			if (owningType == null) owningType = typeNode;
		}
	}

	boolean skip = false;

	if (methodCall.receiver instanceof ThisReference && (((ThisReference)methodCall.receiver).bits & ASTNode.IsImplicitThis) != 0) skip = true;
	if (methodCall.receiver instanceof SuperReference) skip = true;
	if (methodCall.receiver instanceof NameReference) {
		Binding binding = ((NameReference)methodCall.receiver).binding;
		if (binding instanceof TypeBinding) skip = true;
	}
	// It's impossible to resolve the right method without types
	if (Reflection.argumentsHaveErrors != null) {
		try {
			if ((Boolean) Reflection.argumentsHaveErrors.get(methodCall)) skip = true;
		} catch (IllegalAccessException ignore) {
			// ignore
		}
	}

private static interface PostponedError {
	public void fire();
}

public static EclipseNode getTypeNode(TypeDeclaration decl) {
	CompilationUnitDeclaration cud = decl.scope.compilationUnitScope().referenceContext;
	EclipseAST astNode = TransformEclipseAST.getAST(cud, false);
	EclipseNode node = astNode.get(decl);
	if (node == null) {
		astNode = TransformEclipseAST.getAST(cud, true);
		node = astNode.get(decl);
	}
	return node;
}

public static Annotation getAnnotation(Class<? extends java.lang.annotation.Annotation> expectedType, EclipseNode node) {
	TypeDeclaration decl = (TypeDeclaration) node.get();
	if (decl.annotations != null) for (Annotation ann : decl.annotations) {
		if (EclipseHandlerUtil.typeMatches(expectedType, node, ann.type)) return ann;
	}
	return null;
}

static EclipseNode upToType(EclipseNode typeNode) {
	EclipseNode node = typeNode;
	do {
		node = node.up();
	} while ((node != null) && (node.getKind() != Kind.TYPE));
	return node;
}

static List<Extension> getApplicableExtensionMethods(EclipseNode typeNode, Annotation ann, TypeBinding receiverType) {
	List<Extension> extensions = new ArrayList<Extension>();
	if ((typeNode != null) && (ann != null) && (receiverType != null)) {
		BlockScope blockScope = ((TypeDeclaration) typeNode.get()).initializerScope;
		EclipseNode annotationNode = typeNode.getNodeFor(ann);
		AnnotationValues<ExtensionMethod> annotation = createAnnotation(ExtensionMethod.class, annotationNode);
		boolean suppressBaseMethods = false;
		try {
			suppressBaseMethods = annotation.getInstance().suppressBaseMethods();
		} catch (AnnotationValueDecodeFail fail) {
			fail.owner.setError(fail.getMessage(), fail.idx);
		}
		for (Object extensionMethodProvider : annotation.getActualExpressions("value")) {
			if (extensionMethodProvider instanceof ClassLiteralAccess) {
				TypeBinding binding = ((ClassLiteralAccess) extensionMethodProvider).type.resolveType(blockScope);
				if (binding == null) continue;
				if (!binding.isClass() && !binding.isEnum()) continue;
				Extension e = new Extension();
				e.extensionMethods = getApplicableExtensionMethodsDefinedInProvider(typeNode, (ReferenceBinding) binding, receiverType);
				e.suppressBaseMethods = suppressBaseMethods;
				extensions.add(e);
			}
		}
	}
	return extensions;
}

private static List<MethodBinding> getApplicableExtensionMethodsDefinedInProvider(EclipseNode typeNode, ReferenceBinding extensionMethodProviderBinding,
		TypeBinding receiverType) {

	List<MethodBinding> extensionMethods = new ArrayList<MethodBinding>();
	for (MethodBinding method : extensionMethodProviderBinding.methods()) {
		if (!method.isStatic()) continue;
		if (!method.isPublic()) continue;
		if (method.parameters == null || method.parameters.length == 0) continue;
		TypeBinding firstArgType = method.parameters[0];
		if (receiverType.isProvablyDistinct(firstArgType) && !receiverType.isCompatibleWith(firstArgType.erasure())) continue;
		extensionMethods.add(method);
	}
	return extensionMethods;
}

private static final FieldAugment<MessageSend, PostponedError> MessageSend_postponedErrors = FieldAugment.augment(MessageSend.class, PostponedError.class, "lombok$postponedErrors");

public static boolean handleValForLocalDeclaration(LocalDeclaration local, BlockScope scope) {
	if (local == null || !LocalDeclaration.class.equals(local.getClass())) return false;
	boolean decomponent = false;

	boolean val = isVal(local, scope);
	boolean var = isVar(local, scope);
	if (!(val || var)) return false;

	if (val) {
		StackTraceElement[] st = new Throwable().getStackTrace();
		for (int i = 0; i < st.length - 2 && i < 10; i++) {
			if (st[i].getClassName().equals("lombok.launch.PatchFixesHider$Val")) {
				boolean valInForStatement = 
					st[i + 1].getClassName().equals("org.eclipse.jdt.internal.compiler.ast.LocalDeclaration") &&
					st[i + 2].getClassName().equals("org.eclipse.jdt.internal.compiler.ast.ForStatement");
				if (valInForStatement) return false;
				break;
			}
		}
	}

	Expression init = local.initialization;
	if (init == null && Reflection.initCopyField != null) {
		try {
			init = (Expression) Reflection.initCopyField.get(local);
		} catch (Exception e) {
			// init remains null.
		}
	}

	if (init == null && Reflection.iterableCopyField != null) {
		try {
			init = (Expression) Reflection.iterableCopyField.get(local);
			decomponent = true;
		} catch (Exception e) {
			// init remains null.
		}
	}

	TypeReference replacement = null;

	if (init != null) {
		if (init.getClass().getName().equals("org.eclipse.jdt.internal.compiler.ast.LambdaExpression")) {
			return false;
		}

		TypeBinding resolved = null;
		Constant oldConstant = init.constant;
		try {
			resolved = decomponent ? getForEachComponentType(init, scope) : resolveForExpression(init, scope);
		} catch (NullPointerException e) {
			// This definitely occurs if as part of resolving the initializer expression, a
			// lambda expression in it must also be resolved (such as when lambdas are part of
			// a ternary expression). This can't result in a viable 'val' matching, so, we
			// just go with 'Object' and let the IDE print the appropriate errors.
			resolved = null;
		}
		if (resolved != null) {
			try {
				replacement = makeType(resolved, local.type, false);
				if (!decomponent) init.resolvedType = replacement.resolveType(scope);
			} catch (Exception e) {
				// Some type thing failed.
			}
		} else {
			if (init instanceof MessageSend && ((MessageSend) init).actualReceiverType == null) {
				init.constant = oldConstant;
			}
		}
	}

	if (val) local.modifiers |= ClassFileConstants.AccFinal;
	local.annotations = addValAnnotation(local.annotations, local.type, scope);
	local.type = replacement != null ? replacement : new QualifiedTypeReference(TypeConstants.JAVA_LANG_OBJECT, poss(local.type, 3));
	return false;
}

private static boolean isVar(LocalDeclaration local, BlockScope scope) {
	return is(local.type, scope, "lombok.experimental.var") || is(local.type, scope, "lombok.var");
}

private static boolean isVal(LocalDeclaration local, BlockScope scope) {
	return is(local.type, scope, "lombok.val");
}

@Provides(JavacASTVisitor.class)
@HandlerPriority(HANDLE_DELEGATE_PRIORITY + 100) // run slightly after HandleDelegate; resolution needs to work, so if the RHS expression is i.e. a call to a generated getter, we have to run after that getter has been generated.
@ResolutionResetNeeded
public class HandleVal extends JavacASTAdapter {

	private static boolean eq(String typeTreeToString, String key) {
		return typeTreeToString.equals(key) || typeTreeToString.equals("lombok." + key) || typeTreeToString.equals("lombok.experimental." + key);
	}

	@SuppressWarnings("deprecation") @Override
	public void visitLocal(JavacNode localNode, JCVariableDecl local) {
		JCTree typeTree = local.vartype;
		if (typeTree == null) return;
		String typeTreeToString = typeTree.toString();
		JavacNode typeNode = localNode.getNodeFor(typeTree);

		if (!(eq(typeTreeToString, "val") || eq(typeTreeToString, "var"))) return;
		boolean isVal = typeMatches(val.class, localNode, typeTree);
		boolean isVar = typeMatches(var.class, localNode, typeTree);
		if (!(isVal || isVar)) return;

		if (isVal) handleFlagUsage(localNode, ConfigurationKeys.VAL_FLAG_USAGE, "val");
		if (isVar) handleFlagUsage(localNode, ConfigurationKeys.VAR_FLAG_USAGE, "var");

		JCTree parentRaw = localNode.directUp().get();
		if (isVal && parentRaw instanceof JCForLoop) {
			localNode.addError("'val' is not allowed in old-style for loops");
			return;
		}

		if (parentRaw instanceof JCForLoop && ((JCForLoop) parentRaw).getInitializer().size() > 1) {
			localNode.addError("'var' is not allowed in old-style for loops if there is more than 1 initializer");
			return;
		}

		JCExpression rhsOfEnhancedForLoop = null;
		if (local.init == null) {
			if (parentRaw instanceof JCEnhancedForLoop) {
				JCEnhancedForLoop efl = (JCEnhancedForLoop) parentRaw;
				if (efl.var == local) rhsOfEnhancedForLoop = efl.expr;
			}
		}

		final String annotation = typeTreeToString;
		if (rhsOfEnhancedForLoop == null && local.init == null) {
			localNode.addError("'" + annotation + "' on a local variable requires an initializer expression");
			return;
		}

		if (local.init instanceof JCNewArray && ((JCNewArray)local.init).elemtype == null) {
			localNode.addError("'" + annotation + "' is not compatible with array initializer expressions. Use the full form (new int[] { ... } instead of just { ... })");
			return;
		}

		if (localNode.shouldDeleteLombokAnnotations()) {
			JavacHandlerUtil.deleteImportFromCompilationUnit(localNode, val.class.getName());
			JavacHandlerUtil.deleteImportFromCompilationUnit(localNode, lombok.experimental.var.class.getName());
			JavacHandlerUtil.deleteImportFromCompilationUnit(localNode, var.class.getName());
		}

		if (isVal) local.mods.flags |= Flags.FINAL;

		if (!localNode.shouldDeleteLombokAnnotations()) {
			JCAnnotation valAnnotation = recursiveSetGeneratedBy(localNode.getTreeMaker().Annotation(local.vartype, List.<JCExpression>nil()), typeNode);
			local.mods.annotations = local.mods.annotations == null ? List.of(valAnnotation) : local.mods.annotations.append(valAnnotation);
		}

		if (JavacResolution.platformHasTargetTyping()) {
			local.vartype = localNode.getAst().getTreeMaker().Ident(localNode.getAst().toName("___Lombok_VAL_Attrib__"));
		} else {
			local.vartype = JavacResolution.createJavaLangObject(localNode.getAst());
		}

		Type type;
		try {
			if (rhsOfEnhancedForLoop == null) {
				if (local.init.type == null) {
					if (isVar && local.init instanceof JCLiteral && ((JCLiteral) local.init).value == null) {
						localNode.addError("variable initializer is 'null'");
					}
					JavacResolution resolver = new JavacResolution(localNode.getContext());
					try {
						type = ((JCExpression) resolver.resolveMethodMember(localNode).get(local.init)).type;
					} catch (RuntimeException e) {
						System.err.println("Exception while resolving: " + localNode + "(" + localNode.getFileName() + ")");
						throw e;
					}
				} else {
					type = local.init.type;
					if (type.isErroneous()) {
						try {
							JavacResolution resolver = new JavacResolution(localNode.getContext());
							local.type = Symtab.instance(localNode.getContext()).unknownType;
							type = ((JCExpression) resolver.resolveMethodMember(localNode).get(local.init)).type;
						} catch (RuntimeException e) {
							System.err.println("Exception while resolving: " + localNode + "(" + localNode.getFileName() + ")");
							throw e;
						}
					}
				}
			} else {
				if (rhsOfEnhancedForLoop.type == null) {
					JavacResolution resolver = new JavacResolution(localNode.getContext());
					type = ((JCExpression) resolver.resolveMethodMember(localNode.directUp()).get(rhsOfEnhancedForLoop)).type;
				} else {
					type = rhsOfEnhancedForLoop.type;
				}
			}

			try {
				JCExpression replacement;

				if (rhsOfEnhancedForLoop != null) {
					Type componentType = JavacResolution.ifTypeIsIterableToComponent(type, localNode.getAst());
					if (componentType == null) replacement = JavacResolution.createJavaLangObject(localNode.getAst());
					else replacement = JavacResolution.typeToJCTree(componentType, localNode.getAst(), false);
				} else {
					replacement = JavacResolution.typeToJCTree(type, localNode.getAst(), false);
				}

				if (replacement != null) {
					local.vartype = replacement;
				} else {
					local.vartype = JavacResolution.createJavaLangObject(localNode.getAst());
				}
				localNode.getAst().setChanged();
			} catch (JavacResolution.TypeNotConvertibleException e) {
				localNode.addError("Cannot use '" + annotation + "' here because initializer expression does not have a representable type: " + e.getMessage());
				local.vartype = JavacResolution.createJavaLangObject(localNode.getAst());
			}
		} catch (RuntimeException e) {
			local.vartype = JavacResolution.createJavaLangObject(localNode.getAst());
			throw e;
		} finally {
			recursiveSetGeneratedBy(local.vartype, typeNode);
		}
	}
}

private static JCExpression typeToJCTree0(Type type, JavacAST ast, boolean allowCompound, boolean allowVoid, boolean allowCapture) throws TypeNotConvertibleException {
	// NB: There's such a thing as maker.Type(type), but this doesn't work very well; it screws up anonymous classes, captures, and adds an extra prefix dot for some reason too.
	//  -- so we write our own take on that here.

	JavacTreeMaker maker = ast.getTreeMaker();

	if (CTC_BOT.equals(typeTag(type))) return createJavaLangObject(ast);
	if (CTC_VOID.equals(typeTag(type))) return allowVoid ? primitiveToJCTree(type.getKind(), maker) : createJavaLangObject(ast);
	if (type.isPrimitive()) return primitiveToJCTree(type.getKind(), maker);
	if (type.isErroneous()) throw new TypeNotConvertibleException("Type cannot be resolved");

	TypeSymbol symbol = type.asElement();
	List<Type> generics = type.getTypeArguments();

	JCExpression replacement = null;

	if (symbol == null) throw new TypeNotConvertibleException("Null or compound type");

	if (symbol.name.length() == 0) {
		// Anonymous inner class
		if (type instanceof ClassType) {
			Type winner = null;
			int winLevel = 0; // 100 = array, 50 = class, 20 = typevar, 15 = wildcard, 10 = interface, 1 = Object.
			Type supertype = ((ClassType) type).supertype_field;
			List<Type> ifaces = ((ClassType) type).interfaces_field;
			for (Type t : concat(supertype, ifaces)) {
				int level = 0;
				if (t instanceof ArrayType) level = 100;
				else if (t instanceof TypeVar) level = 20;
				else if (t instanceof WildcardType) level = 15;
				else if (t.isInterface()) level = 10;
				else if (isObject(t)) level = 1;
				else if (t instanceof ClassType) level = 50;
				else level = 5;

				if (winLevel > level) continue;
				if (winLevel < level) {
					winner = t;
					winLevel = level;
					continue;
				}
				if (compare(winner.tsym.getQualifiedName(), t.tsym.getQualifiedName()) < 0) winner = t;
			}
			if (winner == null) return createJavaLangObject(ast);
			return typeToJCTree(winner, ast, allowCompound, allowVoid, allowCapture);
		}
		throw new TypeNotConvertibleException("Anonymous inner class");
	}

private static TypeBinding resolveForExpression(Expression collection, BlockScope scope) {
	try {
		return collection.resolveType(scope);
	} catch (ArrayIndexOutOfBoundsException e) {
		// Known cause of issues; for example: val e = mth("X"), where mth takes 2 arguments.
		return null;
	} catch (AbortCompilation e) {
		if (collection instanceof ConditionalExpression) {
			ConditionalExpression cexp = (ConditionalExpression) collection;
			Expression ifTrue = cexp.valueIfTrue;
			Expression ifFalse = cexp.valueIfFalse;
			TypeBinding ifTrueResolvedType = ifTrue.resolvedType;
			CategorizedProblem problem = e.problem;
			if (ifTrueResolvedType != null && ifFalse.resolvedType == null && problem.getCategoryID() == CAT_TYPE) {
				CompilationResult compilationResult = e.compilationResult;
				CategorizedProblem[] problems = compilationResult.problems;
				int problemCount = compilationResult.problemCount;
				for (int i = 0; i < problemCount; ++i) {
					if (problems[i] == problem) {
						problems[i] = null;
						if (i + 1 < problemCount) {
							System.arraycopy(problems, i + 1, problems, i, problemCount - i + 1);
						}
						break;
					}
				}
				compilationResult.removeProblem(problem);
				if (!compilationResult.hasErrors()) {
					clearIgnoreFurtherInvestigationField(scope.referenceContext());
					setValue(getField(CompilationResult.class, "hasMandatoryErrors"), compilationResult, false);
				}

				if (ifFalse instanceof FunctionalExpression) {
					FunctionalExpression functionalExpression = (FunctionalExpression) ifFalse;
					functionalExpression.setExpectedType(ifTrueResolvedType);
				}
				if (ifFalse.resolvedType == null) {
					ifFalse.resolve(scope);
				}

				return ifTrueResolvedType;
			}
		}
		throw e;
	}
}

private static void clearIgnoreFurtherInvestigationField(ReferenceContext currentContext) {
	if (currentContext instanceof AbstractMethodDeclaration) {
		AbstractMethodDeclaration methodDeclaration = (AbstractMethodDeclaration) currentContext;
		methodDeclaration.ignoreFurtherInvestigation = false;
	} else if (currentContext instanceof LambdaExpression) {
		LambdaExpression lambdaExpression = (LambdaExpression) currentContext;
		setValue(getField(LambdaExpression.class, "ignoreFurtherInvestigation"), lambdaExpression, false);

		Scope parent = lambdaExpression.enclosingScope.parent;
		while (parent != null) {
			switch(parent.kind) {
				case Scope.CLASS_SCOPE:
				case Scope.METHOD_SCOPE:
					ReferenceContext parentAST = parent.referenceContext();
					if (parentAST != lambdaExpression) {
						clearIgnoreFurtherInvestigationField(parentAST);
						return;
					}
				default:
					parent = parent.parent;
					break;
			}
		}

	} else if (currentContext instanceof TypeDeclaration) {
		TypeDeclaration typeDeclaration = (TypeDeclaration) currentContext;
		typeDeclaration.ignoreFurtherInvestigation = false;
	} else if (currentContext instanceof CompilationUnitDeclaration) {
		CompilationUnitDeclaration typeDeclaration = (CompilationUnitDeclaration) currentContext;
		typeDeclaration.ignoreFurtherInvestigation = false;
	} else {
		throw new UnsupportedOperationException("clearIgnoreFurtherInvestigationField for " + currentContext.getClass());
	}
}

private static void setValue(Field field, Object object, Object value) {
	try {
		field.set(object, value);
	} catch (IllegalAccessException e) {
		throw sneakyThrow(e);
	}
}

private static void addPatchesForVal(ScriptManager sm) {
	final String LOCALDECLARATION_SIG = "org.eclipse.jdt.internal.compiler.ast.LocalDeclaration";
	final String FOREACHSTATEMENT_SIG = "org.eclipse.jdt.internal.compiler.ast.ForeachStatement";
	final String EXPRESSION_SIG = "org.eclipse.jdt.internal.compiler.ast.Expression";
	final String BLOCKSCOPE_SIG = "org.eclipse.jdt.internal.compiler.lookup.BlockScope";
	final String TYPEBINDING_SIG = "org.eclipse.jdt.internal.compiler.lookup.TypeBinding";
	final String OBJECT_SIG = "java.lang.Object";

	sm.addScript(ScriptBuilder.exitEarly()
			.target(new MethodTarget(LOCALDECLARATION_SIG, "resolve", "void", BLOCKSCOPE_SIG))
			.request(StackRequest.THIS, StackRequest.PARAM1)
			.decisionMethod(new Hook("lombok.launch.PatchFixesHider$Val", "handleValForLocalDeclaration", "boolean", OBJECT_SIG, OBJECT_SIG))
			.build());

	sm.addScript(ScriptBuilder.replaceMethodCall()
			.target(new MethodTarget(LOCALDECLARATION_SIG, "resolve", "void", BLOCKSCOPE_SIG))
			.methodToReplace(new Hook(EXPRESSION_SIG, "resolveType", TYPEBINDING_SIG, BLOCKSCOPE_SIG))
			.requestExtra(StackRequest.THIS)
			.replacementMethod(new Hook("lombok.launch.PatchFixesHider$Val", "skipResolveInitializerIfAlreadyCalled2", TYPEBINDING_SIG, EXPRESSION_SIG, BLOCKSCOPE_SIG, LOCALDECLARATION_SIG))
			.transplant()
			.build());

	sm.addScript(ScriptBuilder.replaceMethodCall()
			.target(new MethodTarget(FOREACHSTATEMENT_SIG, "resolve", "void", BLOCKSCOPE_SIG))
			.methodToReplace(new Hook(EXPRESSION_SIG, "resolveType", TYPEBINDING_SIG, BLOCKSCOPE_SIG))
			.replacementMethod(new Hook("lombok.launch.PatchFixesHider$Val", "skipResolveInitializerIfAlreadyCalled", TYPEBINDING_SIG, EXPRESSION_SIG, BLOCKSCOPE_SIG))
			.transplant()
			.build());

	sm.addScript(ScriptBuilder.exitEarly()
			.target(new MethodTarget(FOREACHSTATEMENT_SIG, "resolve", "void", BLOCKSCOPE_SIG))
			.request(StackRequest.THIS, StackRequest.PARAM1)
			.decisionMethod(new Hook("lombok.launch.PatchFixesHider$Val", "handleValForForEach", "boolean", OBJECT_SIG, OBJECT_SIG))
			.build());
}

private static void patchFixSourceTypeConverter(ScriptManager sm) {
	final String SOURCE_TYPE_CONVERTER_SIG = "org.eclipse.jdt.internal.compiler.parser.SourceTypeConverter";
	final String I_ANNOTATABLE_SIG = "org.eclipse.jdt.core.IAnnotatable";
	final String ANNOTATION_SIG = "org.eclipse.jdt.internal.compiler.ast.Annotation";

	sm.addScriptIfWitness(OSGI_TYPES, ScriptBuilder.wrapReturnValue()
			.target(new MethodTarget(SOURCE_TYPE_CONVERTER_SIG, "convertAnnotations", ANNOTATION_SIG + "[]", I_ANNOTATABLE_SIG))
			.wrapMethod(new Hook("lombok.launch.PatchFixesHider$PatchFixes", "convertAnnotations", ANNOTATION_SIG + "[]", ANNOTATION_SIG + "[]", I_ANNOTATABLE_SIG))
			.request(StackRequest.PARAM1, StackRequest.RETURN_VALUE).build());
}

/** Contains patch code to support {@code val} (eclipse and ecj) */
public static final class Val {
	private static final String BLOCK_SCOPE_SIG = "org.eclipse.jdt.internal.compiler.lookup.BlockScope";
	private static final String LOCAL_DECLARATION_SIG = "org.eclipse.jdt.internal.compiler.ast.LocalDeclaration";
	private static final String FOREACH_STATEMENT_SIG = "org.eclipse.jdt.internal.compiler.ast.ForeachStatement";

	private static final Method HANDLE_VAL_FOR_LOCAL_DECLARATION;
	private static final Method HANDLE_VAL_FOR_FOR_EACH;

	static {
		Class<?> shadowed = Util.shadowLoadClass("lombok.eclipse.agent.PatchVal");
		HANDLE_VAL_FOR_LOCAL_DECLARATION = Util.findMethod(shadowed, "handleValForLocalDeclaration", LOCAL_DECLARATION_SIG, BLOCK_SCOPE_SIG);
		HANDLE_VAL_FOR_FOR_EACH = Util.findMethod(shadowed, "handleValForForEach", FOREACH_STATEMENT_SIG, BLOCK_SCOPE_SIG);
	}

	public static boolean handleValForLocalDeclaration(Object local, Object scope) {
		return (Boolean) Util.invokeMethod(HANDLE_VAL_FOR_LOCAL_DECLARATION, local, scope);
	}

	public static boolean handleValForForEach(Object forEach, Object scope) {
		return (Boolean) Util.invokeMethod(HANDLE_VAL_FOR_FOR_EACH, forEach, scope);
	}

	/** 
	 * Patches local declaration to not call .resolveType() on the initializer expression if we've already done so (calling it twice causes weird errors) 
	 * This and the next method must be transplanted so that the return type is loaded in the correct class loader
	 */
	public static TypeBinding skipResolveInitializerIfAlreadyCalled(Expression expr, BlockScope scope) {
		if (expr.resolvedType != null) return expr.resolvedType;
		try {
			return expr.resolveType(scope);
		} catch (NullPointerException e) {
			return null;
		} catch (ArrayIndexOutOfBoundsException e) {
			// This will occur internally due to for example 'val x = mth("X");', where mth takes 2 arguments.
			return null;
		}
	}

	public static TypeBinding skipResolveInitializerIfAlreadyCalled2(Expression expr, BlockScope scope, LocalDeclaration decl) {
		if (decl != null && LocalDeclaration.class.equals(decl.getClass()) && expr.resolvedType != null) return expr.resolvedType;
		try {
			return expr.resolveType(scope);
		} catch (NullPointerException e) {
			return null;
		} catch (ArrayIndexOutOfBoundsException e) {
			// This will occur internally due to for example 'val x = mth("X");', where mth takes 2 arguments.
			return null;
		}
	}
}

public static void addFinalAndValAnnotationToVariableDeclarationStatement(Object converter, VariableDeclarationStatement out, LocalDeclaration in) {
	@SuppressWarnings("unchecked") List<IExtendedModifier> modifiers = out.modifiers();
	addFinalAndValAnnotationToModifierList(converter, modifiers, out.getAST(), in);
}

