package lombok.bytecode;

import org.objectweb.asm.ClassReader;
import org.objectweb.asm.ClassVisitor;
import org.objectweb.asm.ClassWriter;
import org.objectweb.asm.MethodVisitor;
import org.objectweb.asm.Opcodes;
import org.objectweb.asm.commons.JSRInlinerAdapter;

class AsmUtil {
	private AsmUtil() {
		throw new UnsupportedOperationException();
	}

	static byte[] fixJSRInlining(byte[] byteCode) {
		ClassReader reader = new ClassReader(byteCode);
		ClassWriter writer = new FixedClassWriter(reader, 0);

		ClassVisitor visitor = new ClassVisitor(Opcodes.ASM9, writer) {
			@Override public MethodVisitor visitMethod(int access, String name, String desc, String signature, String[] exceptions) {
				return new JSRInlinerAdapter(super.visitMethod(access, name, desc, signature, exceptions), access, name, desc, signature, exceptions);
			}
		};

		reader.accept(visitor, 0);
		return writer.toByteArray();
	}
}

/**
 * Generates a new statement that checks if the given local variable is null, and if so, throws a specified exception with the
 * variable name as message.
 */
public static Statement generateNullCheck(TypeReference type, char[] variable, EclipseNode sourceNode, String customMessage) {
	NullCheckExceptionType exceptionType = sourceNode.getAst().readConfiguration(ConfigurationKeys.NON_NULL_EXCEPTION_TYPE);
	if (exceptionType == null) exceptionType = NullCheckExceptionType.NULL_POINTER_EXCEPTION;

	ASTNode source = sourceNode.get();

	int pS = source.sourceStart, pE = source.sourceEnd;
	long p = (long) pS << 32 | pE;

	if (type != null && isPrimitive(type)) return null;
	SingleNameReference varName = new SingleNameReference(variable, p);
	setGeneratedBy(varName, source);

	StringLiteral message = new StringLiteral(exceptionType.toExceptionMessage(new String(variable), customMessage).toCharArray(), pS, pE, 0);
	setGeneratedBy(message, source);

	LombokImmutableList<String> method = exceptionType.getMethod();
	if (method != null) {

		MessageSend invocation = new MessageSend();
		invocation.sourceStart = pS; invocation.sourceEnd = pE;
		setGeneratedBy(invocation, source);

		char[][] utilityTypeName = new char[method.size() - 1][];
		for (int i = 0; i < method.size() - 1; i++) {
			utilityTypeName[i] = method.get(i).toCharArray();
		}

		invocation.receiver = new QualifiedNameReference(utilityTypeName, new long[method.size() - 1], pS, pE);
		setGeneratedBy(invocation.receiver, source);
		invocation.selector = method.get(method.size() - 1).toCharArray();
		invocation.arguments = new Expression[] {varName, message};
		return invocation;
	}

	AllocationExpression exception = new AllocationExpression();
	setGeneratedBy(exception, source);

	NullLiteral nullLiteral = new NullLiteral(pS, pE);
	setGeneratedBy(nullLiteral, source);

	int equalOperator = exceptionType == NullCheckExceptionType.ASSERTION ? OperatorIds.NOT_EQUAL : OperatorIds.EQUAL_EQUAL; 
	EqualExpression equalExpression = new EqualExpression(varName, nullLiteral, equalOperator);
	equalExpression.sourceStart = pS; equalExpression.statementEnd = equalExpression.sourceEnd = pE;
	setGeneratedBy(equalExpression, source);

	if (exceptionType == NullCheckExceptionType.ASSERTION) {
		Statement assertStatement = new AssertStatement(message, equalExpression, pS);
		setGeneratedBy(assertStatement, source);
		return assertStatement;
	}

	String exceptionTypeStr = exceptionType.getExceptionType();
	int partCount = 1;
	for (int i = 0; i < exceptionTypeStr.length(); i++) if (exceptionTypeStr.charAt(i) == '.') partCount++;
	long[] ps = new long[partCount];
	Arrays.fill(ps, 0L);
	exception.type = new QualifiedTypeReference(fromQualifiedName(exceptionTypeStr), ps);
	setGeneratedBy(exception.type, source);
	exception.arguments = new Expression[] {message};

	ThrowStatement throwStatement = new ThrowStatement(exception, pS, pE);
	setGeneratedBy(throwStatement, source);

	Block throwBlock = new Block(0);
	throwBlock.statements = new Statement[] {throwStatement};
	throwBlock.sourceStart = pS; throwBlock.sourceEnd = pE;
	setGeneratedBy(throwBlock, source);
	IfStatement ifStatement = new IfStatement(equalExpression, throwBlock, 0, 0);
	setGeneratedBy(ifStatement, source);
	return ifStatement;
}

@Override public void handle(AnnotationValues<NonNull> annotation, JCAnnotation ast, JavacNode annotationNode) {
	handleFlagUsage(annotationNode, ConfigurationKeys.NON_NULL_FLAG_USAGE, "@NonNull");
	if (annotationNode.up().getKind() == Kind.FIELD) {
		// This is meaningless unless the field is used to generate a method (@Setter, @RequiredArgsConstructor, etc),
		// but in that case those handlers will take care of it. However, we DO check if the annotation is applied to
		// a primitive, because those handlers trigger on any annotation named @NonNull and we only want the warning
		// behaviour on _OUR_ 'lombok.NonNull'.

		try {
			if (isPrimitive(((JCVariableDecl) annotationNode.up().get()).vartype)) {
				annotationNode.addWarning("@NonNull is meaningless on a primitive.");
			}
		} catch (Exception ignore) {}

		JCVariableDecl fDecl = (JCVariableDecl) annotationNode.up().get();
		if ((fDecl.mods.flags & RECORD) != 0) {
			// well, these kinda double as parameters (of the compact constructor), so we do some work here.

			List<JCMethodDecl> compactConstructors = addCompactConstructorIfNeeded(annotationNode.up().up(), annotationNode);
			for (JCMethodDecl ctr : compactConstructors) {
				addNullCheckIfNeeded(ctr, annotationNode.up(), annotationNode);
			}
		}
		return;
	}

	JCMethodDecl declaration;
	JavacNode paramNode;

	switch (annotationNode.up().getKind()) {
	case ARGUMENT:
		paramNode = annotationNode.up();
		break;
	case TYPE_USE:
		JavacNode typeNode = annotationNode.directUp();
		paramNode = typeNode.directUp();
		break;
	default:
		return;
	}

	if (paramNode.getKind() != Kind.ARGUMENT) return;
	try {
		declaration = (JCMethodDecl) paramNode.up().get();
	} catch (Exception e) {
		return;
	}

	if (declaration.body == null) {
		// This used to be a warning, but as @NonNull also has a documentary purpose, better to not warn about this. Since 1.16.7
		return;
	}

	if ((declaration.mods.flags & (GENERATED_MEMBER | COMPACT_RECORD_CONSTRUCTOR)) != 0) {
		// The 'real' annotations are on the `record Foo(@NonNull Obj x)` part and we just see these
		// syntax-sugared over. We deal with it on the field declaration variant, as those are always there,
		// not dependent on whether you write out the compact constructor or not.
		return;
	}

	addNullCheckIfNeeded(declaration, paramNode, annotationNode);
}

public boolean isNullCheck(JCStatement stat) {
	return returnVarNameIfNullCheck(stat) != null;
}

private void handle0(Annotation ast, EclipseNode annotationNode, boolean force) {
	handleFlagUsage(annotationNode, ConfigurationKeys.NON_NULL_FLAG_USAGE, "@NonNull");

	if (annotationNode.up().getKind() == Kind.FIELD) {
		// This is meaningless unless the field is used to generate a method (@Setter, @RequiredArgsConstructor, etc),
		// but in that case those handlers will take care of it. However, we DO check if the annotation is applied to
		// a primitive, because those handlers trigger on any annotation named @NonNull and we only want the warning
		// behaviour on _OUR_ 'lombok.NonNull'.
		EclipseNode fieldNode = annotationNode.up();
		EclipseNode typeNode = fieldNode.up();

		try {
			if (isPrimitive(((AbstractVariableDeclaration) annotationNode.up().get()).type)) {
				annotationNode.addWarning("@NonNull is meaningless on a primitive.");
				return;
			}
		} catch (Exception ignore) {}

		if (isRecord(typeNode)) {
			// well, these kinda double as parameters (of the compact constructor), so we do some work here.
			// NB:Tthe diet parse run already added an explicit compact constructor if we need to take any actions.
			EclipseNode compactConstructor = findCompactConstructor(typeNode);

			if (compactConstructor != null) {
				addNullCheckIfNeeded((AbstractMethodDeclaration) compactConstructor.get(), (AbstractVariableDeclaration) fieldNode.get(), annotationNode);
			}
		}

		return;
	}

	Argument param;
	EclipseNode paramNode;
	AbstractMethodDeclaration declaration;

	switch (annotationNode.up().getKind()) {
	case ARGUMENT:
		paramNode = annotationNode.up();
		break;
	case TYPE_USE:
		EclipseNode typeNode = annotationNode.directUp();
		boolean ok = false;
		ASTNode astNode = typeNode.get();
		if (astNode instanceof TypeReference) {
			Annotation[] anns = EclipseAST.getTopLevelTypeReferenceAnnotations((TypeReference) astNode);
			if (anns == null) return;
			for (Annotation ann : anns) if (ast == ann) ok = true;
		}
		if (!ok) return;
		paramNode = typeNode.directUp();
		break;
	default:
		return;
	}

	try {
		param = (Argument) paramNode.get();
		declaration = (AbstractMethodDeclaration) paramNode.up().get();
	} catch (Exception e) {
		return;
	}

	if (!force && isGenerated(declaration)) return;

	if (declaration.isAbstract()) {
		// This used to be a warning, but as @NonNull also has a documentary purpose, better to not warn about this. Since 1.16.7
		return;
	}

	addNullCheckIfNeeded(declaration, param, annotationNode);
	paramNode.up().rebuild();
}

private void addNullCheckIfNeeded(AbstractMethodDeclaration declaration, AbstractVariableDeclaration param, EclipseNode annotationNode) {
	// Possibly, if 'declaration instanceof ConstructorDeclaration', fetch declaration.constructorCall, search it for any references to our parameter,
	// and if they exist, create a new method in the class: 'private static <T> T lombok$nullCheck(T expr, String msg) {if (expr == null) throw NPE; return expr;}' and
	// wrap all references to it in the super/this to a call to this method.

	Statement nullCheck = generateNullCheck(param, annotationNode, null);

	if (nullCheck == null) {
		// @NonNull applied to a primitive. Kinda pointless. Let's generate a warning.
		annotationNode.addWarning("@NonNull is meaningless on a primitive.");
		return;
	}

	if (declaration.statements == null) {
		declaration.statements = new Statement[] {nullCheck};
	} else {
		char[] expectedName = param.name;
		/* Abort if the null check is already there, delving into try and synchronized statements */ {
			Statement[] stats = declaration.statements;
			int idx = 0;
			while (stats != null && stats.length > idx) {
				Statement stat = stats[idx++];
				if (stat instanceof TryStatement) {
					stats = ((TryStatement) stat).tryBlock.statements;
					idx = 0;
					continue;
				}
				if (stat instanceof SynchronizedStatement) {
					stats = ((SynchronizedStatement) stat).block.statements;
					idx = 0;
					continue;
				}
				char[] varNameOfNullCheck = returnVarNameIfNullCheck(stat);
				if (varNameOfNullCheck == null) break;
				if (Arrays.equals(varNameOfNullCheck, expectedName)) return;
			}
		}

		Statement[] newStatements = new Statement[declaration.statements.length + 1];
		int skipOver = 0;
		for (Statement stat : declaration.statements) {
			if (isGenerated(stat) && isNullCheck(stat)) skipOver++;
			else break;
		}
		System.arraycopy(declaration.statements, 0, newStatements, 0, skipOver);
		System.arraycopy(declaration.statements, skipOver, newStatements, skipOver + 1, declaration.statements.length - skipOver);
		newStatements[skipOver] = nullCheck;
		declaration.statements = newStatements;
	}
}

public boolean isNullCheck(Statement stat) {
	return returnVarNameIfNullCheck(stat) != null;
}

@SuppressWarnings("deprecation") public static JCMethodDecl createConstructor(AccessLevel level, List<JCAnnotation> onConstructor, JavacNode typeNode, List<JavacNode> fieldsToParam, boolean forceDefaults, JavacNode source) {
	JavacTreeMaker maker = typeNode.getTreeMaker();

	boolean isEnum = (((JCClassDecl) typeNode.get()).mods.flags & Flags.ENUM) != 0;
	if (isEnum) level = AccessLevel.PRIVATE;

	boolean addConstructorProperties;

	List<JavacNode> fieldsToDefault = fieldsNeedingBuilderDefaults(typeNode, fieldsToParam);
	List<JavacNode> fieldsToExplicit = forceDefaults ? fieldsNeedingExplicitDefaults(typeNode, fieldsToParam) : List.<JavacNode>nil();

	if (fieldsToParam.isEmpty()) {
		addConstructorProperties = false;
	} else {
		Boolean v = typeNode.getAst().readConfiguration(ConfigurationKeys.ANY_CONSTRUCTOR_ADD_CONSTRUCTOR_PROPERTIES);
		addConstructorProperties = v != null ? v.booleanValue() :
			Boolean.FALSE.equals(typeNode.getAst().readConfiguration(ConfigurationKeys.ANY_CONSTRUCTOR_SUPPRESS_CONSTRUCTOR_PROPERTIES));
	}

	ListBuffer<JCStatement> nullChecks = new ListBuffer<JCStatement>();
	ListBuffer<JCStatement> assigns = new ListBuffer<JCStatement>();
	ListBuffer<JCVariableDecl> params = new ListBuffer<JCVariableDecl>();

	for (JavacNode fieldNode : fieldsToParam) {
		JCVariableDecl field = (JCVariableDecl) fieldNode.get();
		Name fieldName = removePrefixFromField(fieldNode);
		Name rawName = field.name;
		List<JCAnnotation> copyableAnnotations = findCopyableAnnotations(fieldNode);
		long flags = JavacHandlerUtil.addFinalIfNeeded(Flags.PARAMETER, typeNode.getContext());
		JCExpression pType = cloneType(fieldNode.getTreeMaker(), field.vartype, source);
		JCVariableDecl param = maker.VarDef(maker.Modifiers(flags, copyableAnnotations), fieldName, pType, null);
		params.append(param);
		if (hasNonNullAnnotations(fieldNode)) {
			JCStatement nullCheck = generateNullCheck(maker, param, source);
			if (nullCheck != null) nullChecks.append(nullCheck);
		}
		JCFieldAccess thisX = maker.Select(maker.Ident(fieldNode.toName("this")), rawName);
		JCExpression assign = maker.Assign(thisX, maker.Ident(fieldName));
		assigns.append(maker.Exec(assign));
	}

	for (JavacNode fieldNode : fieldsToExplicit) {
		JCVariableDecl field = (JCVariableDecl) fieldNode.get();
		Name rawName = field.name;
		JCFieldAccess thisX = maker.Select(maker.Ident(fieldNode.toName("this")), rawName);
		JCExpression assign = maker.Assign(thisX, getDefaultExpr(maker, field.vartype));
		assigns.append(maker.Exec(assign));
	}

	for (JavacNode fieldNode : fieldsToDefault) {
		JCVariableDecl field = (JCVariableDecl) fieldNode.get();
		Name rawName = field.name;
		Name fieldName = removePrefixFromField(fieldNode);
		Name nameOfDefaultProvider = typeNode.toName("$default$" + fieldName);
		JCFieldAccess thisX = maker.Select(maker.Ident(fieldNode.toName("this")), rawName);
		JCExpression assign = maker.Assign(thisX, maker.Apply(List.<JCExpression>nil(), maker.Select(maker.Ident(((JCClassDecl) typeNode.get()).name), nameOfDefaultProvider), List.<JCExpression>nil()));
		assigns.append(maker.Exec(assign));
	}

	JCModifiers mods = maker.Modifiers(toJavacModifier(level), List.<JCAnnotation>nil());
	if (addConstructorProperties && !isLocalType(typeNode) && LombokOptionsFactory.getDelombokOptions(typeNode.getContext()).getFormatPreferences().generateConstructorProperties()) {
		addConstructorProperties(mods, typeNode, fieldsToParam);
	}
	if (onConstructor != null) mods.annotations = mods.annotations.appendList(copyAnnotations(onConstructor));
	return recursiveSetGeneratedBy(maker.MethodDef(mods, typeNode.toName("<init>"),
		null, List.<JCTypeParameter>nil(), params.toList(), List.<JCExpression>nil(),
		maker.Block(0L, nullChecks.appendList(assigns).toList()), null), source);
}

@SuppressWarnings("deprecation") public static ConstructorDeclaration createConstructor(
	AccessLevel level, EclipseNode type, Collection<EclipseNode> fieldsToParam, boolean forceDefaults,
	EclipseNode sourceNode, List<Annotation> onConstructor) {

	ASTNode source = sourceNode.get();
	TypeDeclaration typeDeclaration = ((TypeDeclaration) type.get());
	long p = (long) source.sourceStart << 32 | source.sourceEnd;

	boolean isEnum = (((TypeDeclaration) type.get()).modifiers & ClassFileConstants.AccEnum) != 0;

	if (isEnum) level = AccessLevel.PRIVATE;

	List<EclipseNode> fieldsToDefault = fieldsNeedingBuilderDefaults(type, fieldsToParam);
	List<EclipseNode> fieldsToExplicit = forceDefaults ? fieldsNeedingExplicitDefaults(type, fieldsToParam) : Collections.<EclipseNode>emptyList();

	boolean addConstructorProperties;
	if (fieldsToParam.isEmpty()) {
		addConstructorProperties = false;
	} else {
		Boolean v = type.getAst().readConfiguration(ConfigurationKeys.ANY_CONSTRUCTOR_ADD_CONSTRUCTOR_PROPERTIES);
		addConstructorProperties = v != null ? v.booleanValue() :
			Boolean.FALSE.equals(type.getAst().readConfiguration(ConfigurationKeys.ANY_CONSTRUCTOR_SUPPRESS_CONSTRUCTOR_PROPERTIES));
	}

	ConstructorDeclaration constructor = new ConstructorDeclaration(((CompilationUnitDeclaration) type.top().get()).compilationResult);

	constructor.modifiers = toEclipseModifier(level);
	constructor.selector = typeDeclaration.name;
	constructor.constructorCall = new ExplicitConstructorCall(ExplicitConstructorCall.ImplicitSuper);
	constructor.constructorCall.sourceStart = source.sourceStart;
	constructor.constructorCall.sourceEnd = source.sourceEnd;
	constructor.thrownExceptions = null;
	constructor.typeParameters = null;
	constructor.bits |= ECLIPSE_DO_NOT_TOUCH_FLAG;
	constructor.bodyStart = constructor.declarationSourceStart = constructor.sourceStart = source.sourceStart;
	constructor.bodyEnd = constructor.declarationSourceEnd = constructor.sourceEnd = source.sourceEnd;
	constructor.arguments = null;

	List<Argument> params = new ArrayList<Argument>();
	List<Statement> assigns = new ArrayList<Statement>();
	List<Statement> nullChecks = new ArrayList<Statement>();

	for (EclipseNode fieldNode : fieldsToParam) {
		FieldDeclaration field = (FieldDeclaration) fieldNode.get();
		char[] rawName = field.name;
		char[] fieldName = removePrefixFromField(fieldNode);
		FieldReference thisX = new FieldReference(rawName, p);
		int s = (int) (p >> 32);
		int e = (int) p;
		thisX.receiver = new ThisReference(s, e);

		Expression assignmentExpr = new SingleNameReference(fieldName, p);

		Assignment assignment = new Assignment(thisX, assignmentExpr, (int) p);
		assignment.sourceStart = (int) (p >> 32); assignment.sourceEnd = assignment.statementEnd = (int) (p >> 32);
		assigns.add(assignment);
		long fieldPos = (((long) field.sourceStart) << 32) | field.sourceEnd;
		Argument parameter = new Argument(fieldName, fieldPos, copyType(field.type, source), Modifier.FINAL);
		Annotation[] copyableAnnotations = findCopyableAnnotations(fieldNode);
		if (hasNonNullAnnotations(fieldNode)) {
			Statement nullCheck = generateNullCheck(parameter, sourceNode, null);
			if (nullCheck != null) nullChecks.add(nullCheck);
		}
		parameter.annotations = copyAnnotations(source, copyableAnnotations);
		if (parameter.annotations != null) {
			parameter.bits |= Eclipse.HasTypeAnnotations;
			constructor.bits |= Eclipse.HasTypeAnnotations;
		}
		params.add(parameter);
	}

@Provides
@HandlerPriority(value = 512) // 2^9; onParameter=@__(@NonNull) has to run first.
public class HandleNonNull extends JavacAnnotationHandler<NonNull> {
	private JCMethodDecl createRecordArgslessConstructor(JavacNode typeNode, JavacNode source, JCMethodDecl existingCtr) {
		JavacTreeMaker maker = typeNode.getTreeMaker();

		java.util.List<JCVariableDecl> fields = new ArrayList<JCVariableDecl>();
		for (JavacNode child : typeNode.down()) {
			if (child.getKind() == Kind.FIELD) {
				JCVariableDecl v = (JCVariableDecl) child.get();
				if ((v.mods.flags & RECORD) != 0) {
					fields.add(v);
				}
			}
		}

		ListBuffer<JCVariableDecl> params = new ListBuffer<JCVariableDecl>();

		for (int i = 0; i < fields.size(); i++) {
			JCVariableDecl arg = fields.get(i);
			JCModifiers mods = maker.Modifiers(GENERATED_MEMBER | Flags.PARAMETER, arg.mods.annotations);
			params.append(maker.VarDef(mods, arg.name, arg.vartype, null));
		}

		JCModifiers mods = maker.Modifiers(toJavacModifier(AccessLevel.PUBLIC) | COMPACT_RECORD_CONSTRUCTOR, List.<JCAnnotation>nil());
		JCBlock body = maker.Block(0L, List.<JCStatement>nil());
		if (existingCtr == null) {
			JCMethodDecl constr = maker.MethodDef(mods, typeNode.toName("<init>"), null, List.<JCTypeParameter>nil(), params.toList(), List.<JCExpression>nil(), body, null);
			return recursiveSetGeneratedBy(constr, source);
		} else {
			existingCtr.mods = mods;
			existingCtr.body = body;
			existingCtr = recursiveSetGeneratedBy(existingCtr, source);
			addSuppressWarningsAll(existingCtr.mods, typeNode, typeNode.getNodeFor(getGeneratedBy(existingCtr)), typeNode.getContext());
			addGenerated(existingCtr.mods, typeNode, typeNode.getNodeFor(getGeneratedBy(existingCtr)), typeNode.getContext());
			return existingCtr;
		}
	}

@Provides
@HandlerPriority(value = 512) // 2^9; onParameter=@__(@NonNull) has to run first.
public class HandleNonNull extends EclipseAnnotationHandler<NonNull> {
	private static final char[] REQUIRE_NON_NULL = "requireNonNull".toCharArray();
	private static final char[] CHECK_NOT_NULL = "checkNotNull".toCharArray();

	public static final HandleNonNull INSTANCE = new HandleNonNull();

	public void fix(EclipseNode method) {
		for (EclipseNode m : method.down()) {
			if (m.getKind() != Kind.ARGUMENT) continue;
			for (EclipseNode c : m.down()) {
				if (c.getKind() == Kind.ANNOTATION) {
					if (annotationTypeMatches(NonNull.class, c)) {
						handle0((Annotation) c.get(), c, true);
					}
				}
			}
		}
	}

	private List<FieldDeclaration> getRecordComponents(EclipseNode typeNode) {
		List<FieldDeclaration> list = new ArrayList<FieldDeclaration>();

		for (EclipseNode child : typeNode.down()) {
			if (child.getKind() == Kind.FIELD) {
				FieldDeclaration fd = (FieldDeclaration) child.get();
				if ((fd.modifiers & AccRecord) != 0) list.add(fd);
			}
		}

		return list;
	}

/**
 * Handles the {@code lombok.FieldDefaults} annotation for eclipse.
 */
@Provides(EclipseASTVisitor.class)
@HandlerPriority(-2048) //-2^11; to ensure @Value picks up on messing with the fields' 'final' state, run earlier.
public class HandleFieldDefaults extends EclipseASTAdapter {
	public boolean generateFieldDefaultsForType(EclipseNode typeNode, EclipseNode pos, AccessLevel level, boolean makeFinal, boolean checkForTypeLevelFieldDefaults) {
		if (checkForTypeLevelFieldDefaults) {
			if (hasAnnotation(FieldDefaults.class, typeNode)) {
				//The annotation will make it happen, so we can skip it.
				return true;
			}
		}

		if (!isClassOrEnum(typeNode)) {
			pos.addError("@FieldDefaults is only supported on a class or an enum.");
			return false;
		}

		for (EclipseNode field : typeNode.down()) {
			if (field.getKind() != Kind.FIELD) continue;
			FieldDeclaration fieldDecl = (FieldDeclaration) field.get();
			if (!filterField(fieldDecl, false)) continue;

			Class<?> t = field.get().getClass();
			if (t == FieldDeclaration.class) {
				// There are various other things that extend FieldDeclaration that really
				// aren't field declarations. Typing 'ma' in an otherwise blank class is a
				// CompletionOnFieldType object (extends FieldDeclaration). If we mess with the
				// modifiers of such a thing, you take away template suggestions such as
				// 'main method'. See issue 411.
				setFieldDefaultsForField(field, pos.get(), level, makeFinal);
			}
		}
		return true;
	}

	public void setFieldDefaultsForField(EclipseNode fieldNode, ASTNode pos, AccessLevel level, boolean makeFinal) {
		FieldDeclaration field = (FieldDeclaration) fieldNode.get();
		if (level != null && level != AccessLevel.NONE) {
			if ((field.modifiers & (ClassFileConstants.AccPublic | ClassFileConstants.AccPrivate | ClassFileConstants.AccProtected)) == 0) {
				if (!hasAnnotation(PackagePrivate.class, fieldNode)) {
					if ((field.modifiers & ClassFileConstants.AccStatic) == 0) {
						field.modifiers |= EclipseHandlerUtil.toEclipseModifier(level);
					}
				}
			}
		}

		if (makeFinal && (field.modifiers & ClassFileConstants.AccFinal) == 0) {
			if (!hasAnnotation(NonFinal.class, fieldNode)) {
				if ((field.modifiers & ClassFileConstants.AccStatic) == 0) {
					field.modifiers |= ClassFileConstants.AccFinal;
				}
			}
		}

		fieldNode.rebuild();
	}

	private static final char[] FIELD_DEFAULTS = "FieldDefaults".toCharArray();

	@Override public void visitType(EclipseNode typeNode, TypeDeclaration type) {
		AnnotationValues<FieldDefaults> fieldDefaults = null;
		EclipseNode source = typeNode;

		boolean levelIsExplicit = false;
		boolean makeFinalIsExplicit = false;
		FieldDefaults fd = null;
		for (EclipseNode jn : typeNode.down()) {
			if (jn.getKind() != Kind.ANNOTATION) continue;
			Annotation ann = (Annotation) jn.get();
			TypeReference typeTree = ann.type;
			if (typeTree == null) continue;
			if (typeTree instanceof SingleTypeReference) {
				char[] t = ((SingleTypeReference) typeTree).token;
				if (!Arrays.equals(t, FIELD_DEFAULTS)) continue;
			} else if (typeTree instanceof QualifiedTypeReference) {
				char[][] t = ((QualifiedTypeReference) typeTree).tokens;
				if (!Eclipse.nameEquals(t, "lombok.experimental.FieldDefaults")) continue;
			} else {
				continue;
			}

			if (!typeMatches(FieldDefaults.class, jn, typeTree)) continue;

			source = jn;
			fieldDefaults = createAnnotation(FieldDefaults.class, jn);
			levelIsExplicit = fieldDefaults.isExplicit("level");
			makeFinalIsExplicit = fieldDefaults.isExplicit("makeFinal");

			handleExperimentalFlagUsage(jn, ConfigurationKeys.FIELD_DEFAULTS_FLAG_USAGE, "@FieldDefaults");

			fd = fieldDefaults.getInstance();
			if (!levelIsExplicit && !makeFinalIsExplicit) {
				jn.addError("This does nothing; provide either level or makeFinal or both.");
			}

			if (levelIsExplicit && fd.level() == AccessLevel.NONE) {
				jn.addError("AccessLevel.NONE doesn't mean anything here. Pick another value.");
				levelIsExplicit = false;
			}
			break;
		}

		if (fd == null && (type.modifiers & (ClassFileConstants.AccInterface | ClassFileConstants.AccAnnotation)) != 0) return;

		boolean defaultToPrivate = levelIsExplicit ? false : Boolean.TRUE.equals(typeNode.getAst().readConfiguration(ConfigurationKeys.FIELD_DEFAULTS_PRIVATE_EVERYWHERE));
		boolean defaultToFinal = makeFinalIsExplicit ? false : Boolean.TRUE.equals(typeNode.getAst().readConfiguration(ConfigurationKeys.FIELD_DEFAULTS_FINAL_EVERYWHERE));

		if (!defaultToPrivate && !defaultToFinal && fieldDefaults == null) return;
		AccessLevel fdAccessLevel = (fieldDefaults != null && levelIsExplicit) ? fd.level() : defaultToPrivate ? AccessLevel.PRIVATE : null;
		boolean fdToFinal = (fieldDefaults != null && makeFinalIsExplicit) ? fd.makeFinal() : defaultToFinal;

		generateFieldDefaultsForType(typeNode, source, fdAccessLevel, fdToFinal, false);
	}
}

/**
 * Handles the {@code lombok.FieldDefaults} annotation for javac.
