/**
 * Creates and returns the abstract builder class and injects it into the annotated class.
 */
private JavacNode generateBuilderAbstractClass(SuperBuilderJob job, JCExpression superclassBuilderClass, List<JCExpression> superclassTypeParams, String classGenericName, String builderGenericName) {
	JavacTreeMaker maker = job.parentType.getTreeMaker();
	JCModifiers mods = maker.Modifiers(Flags.STATIC | Flags.ABSTRACT | Flags.PUBLIC);

	// Keep any type params of the annotated class.
	ListBuffer<JCTypeParameter> allTypeParams = new ListBuffer<JCTypeParameter>();
	allTypeParams.appendList(copyTypeParams(job.sourceNode, job.typeParams));
	// Add builder-specific type params required for inheritable builders.
	// 1. The return type for the build() method, named "C", which extends the annotated class.
	JCExpression annotatedClass = namePlusTypeParamsToTypeReference(maker, job.parentType, job.typeParams);

	allTypeParams.append(maker.TypeParameter(job.toName(classGenericName), List.<JCExpression>of(annotatedClass)));
	// 2. The return type for all setter methods, named "B", which extends this builder class.
	Name builderClassName = job.toName(job.builderClassName);
	ListBuffer<JCExpression> typeParamsForBuilder = getTypeParamExpressions(job.typeParams, maker, job.sourceNode);
	typeParamsForBuilder.append(maker.Ident(job.toName(classGenericName)));
	typeParamsForBuilder.append(maker.Ident(job.toName(builderGenericName)));
	JCTypeApply typeApply = maker.TypeApply(namePlusTypeParamsToTypeReference(maker, job.parentType, builderClassName, false, List.<JCTypeParameter>nil()), typeParamsForBuilder.toList());
	allTypeParams.append(maker.TypeParameter(job.toName(builderGenericName), List.<JCExpression>of(typeApply)));

	JCExpression extending = null;
	if (superclassBuilderClass != null) {
		// If the annotated class extends another class, we want this builder to extend the builder of the superclass.
		// 1. Add the type parameters of the superclass.
		typeParamsForBuilder = getTypeParamExpressions(superclassTypeParams, maker, job.sourceNode);
		// 2. Add the builder type params <C, B>.
		typeParamsForBuilder.append(maker.Ident(job.toName(classGenericName)));
		typeParamsForBuilder.append(maker.Ident(job.toName(builderGenericName)));
		extending = maker.TypeApply(superclassBuilderClass, typeParamsForBuilder.toList());
	}

	JCClassDecl builder = maker.ClassDef(mods, builderClassName, allTypeParams.toList(), extending, List.<JCExpression>nil(), List.<JCTree>nil());
	recursiveSetGeneratedBy(builder, job.sourceNode);
	return injectType(job.parentType, builder);
}

/**
 * Creates and returns the concrete builder implementation class and injects it into the annotated class.
 */
private JavacNode generateBuilderImplClass(SuperBuilderJob job) {
	JavacTreeMaker maker = job.getTreeMaker();
	JCModifiers mods = maker.Modifiers(Flags.STATIC | Flags.PRIVATE | Flags.FINAL);

	// Extend the abstract builder.
	JCExpression extending = namePlusTypeParamsToTypeReference(maker, job.parentType, job.toName(job.builderAbstractClassName), false, List.<JCTypeParameter>nil());

	// Add builder-specific type params required for inheritable builders.
	// 1. The return type for the build() method (named "C" in the abstract builder), which is the annotated class.
	JCExpression annotatedClass = namePlusTypeParamsToTypeReference(maker, job.parentType, job.typeParams);
	// 2. The return type for all setter methods (named "B" in the abstract builder), which is this builder class.
	JCExpression builderImplClassExpression = namePlusTypeParamsToTypeReference(maker, job.parentType, job.toName(job.builderImplClassName), false, job.typeParams);

	ListBuffer<JCExpression> typeParamsForBuilder = getTypeParamExpressions(job.typeParams, maker, job.sourceNode);
	typeParamsForBuilder.append(annotatedClass);
	typeParamsForBuilder.append(builderImplClassExpression);
	extending = maker.TypeApply(extending, typeParamsForBuilder.toList());

	JCClassDecl builder = maker.ClassDef(mods, job.toName(job.builderImplClassName), copyTypeParams(job.parentType, job.typeParams), extending, List.<JCExpression>nil(), List.<JCTree>nil());
	recursiveSetGeneratedBy(builder, job.sourceNode);
	return injectType(job.parentType, builder);
}

private EclipseNode generateBuilderAbstractClass(BuilderJob job, TypeReference superclassBuilderClass, String classGenericName, String builderGenericName) {
	TypeDeclaration parent = (TypeDeclaration) job.parentType.get();
	TypeDeclaration builder = new TypeDeclaration(parent.compilationResult);
	builder.bits |= Eclipse.ECLIPSE_DO_NOT_TOUCH_FLAG;
	builder.modifiers |= ClassFileConstants.AccPublic | ClassFileConstants.AccStatic | ClassFileConstants.AccAbstract;
	builder.name = job.builderClassNameArr;

	// Keep any type params of the annotated class.
	builder.typeParameters = Arrays.copyOf(copyTypeParams(job.typeParams, job.source), job.typeParams.length + 2);
	// Add builder-specific type params required for inheritable builders.
	// 1. The return type for the build() method, named "C", which extends the annotated class.
	TypeParameter o = new TypeParameter();
	o.name = classGenericName.toCharArray();
	o.type = cloneSelfType(job.parentType, job.source);
	builder.typeParameters[builder.typeParameters.length - 2] = o;
	// 2. The return type for all setter methods, named "B", which extends this builder class.
	o = new TypeParameter();
	o.name = builderGenericName.toCharArray();
	TypeReference[] typerefs = appendBuilderTypeReferences(job.typeParams, classGenericName, builderGenericName);
	o.type = generateParameterizedTypeReference(job.parentType, job.builderClassNameArr, false, typerefs, 0);
	builder.typeParameters[builder.typeParameters.length - 1] = o;

	if (superclassBuilderClass != null) builder.superclass = copyType(superclassBuilderClass, job.source);

	builder.createDefaultConstructor(false, true);

	builder.traverse(new SetGeneratedByVisitor(job.source), (ClassScope) null);
	return injectType(job.parentType, builder);
}

private EclipseNode generateBuilderImplClass(BuilderJob job, String builderImplClass) {
	TypeDeclaration parent = (TypeDeclaration) job.parentType.get();
	TypeDeclaration builder = new TypeDeclaration(parent.compilationResult);
	builder.bits |= Eclipse.ECLIPSE_DO_NOT_TOUCH_FLAG;
	builder.modifiers |= ClassFileConstants.AccPrivate | ClassFileConstants.AccStatic | ClassFileConstants.AccFinal;
	builder.name = builderImplClass.toCharArray();

	// Add type params if there are any.
	if (job.typeParams != null && job.typeParams.length > 0) builder.typeParameters = copyTypeParams(job.typeParams, job.source);

	if (job.builderClassName != null) {
		// Extend the abstract builder.
		// 1. Add any type params of the annotated class.
		TypeReference[] typeArgs = new TypeReference[job.typeParams.length + 2];
		for (int i = 0; i < job.typeParams.length; i++) {
			typeArgs[i] = new SingleTypeReference(job.typeParams[i].name, 0);
		}
		// 2. The return type for the build() method (named "C" in the abstract builder), which is the annotated class.
		// 3. The return type for all setter methods (named "B" in the abstract builder), which is this builder class.
		typeArgs[typeArgs.length - 2] = cloneSelfType(job.parentType, job.source);
		typeArgs[typeArgs.length - 1] = createTypeReferenceWithTypeParameters(job.parentType, builderImplClass, job.typeParams);
		builder.superclass = generateParameterizedTypeReference(job.parentType, job.builderClassNameArr, false, typeArgs, 0);
	}

	builder.createDefaultConstructor(false, true);

	builder.traverse(new SetGeneratedByVisitor(job.source), (ClassScope) null);
	return injectType(job.parentType, builder);
}

private java.util.Set<String> gatherUsedTypeNames(TypeParameter[] typeParams, TypeDeclaration td) {
	java.util.HashSet<String> usedNames = new HashSet<String>();

	// 1. Add type parameter names.
	for (TypeParameter typeParam : typeParams)
		usedNames.add(typeParam.toString());

	// 2. Add class name.
	usedNames.add(String.valueOf(td.name));

	// 3. Add used type names.
	if (td.fields != null) {
		for (FieldDeclaration field : td.fields) {
			if (field instanceof Initializer) continue; 
			addFirstToken(usedNames, field.type);
		}
	}

	// 4. Add extends and implements clauses.
	addFirstToken(usedNames, td.superclass);
	if (td.superInterfaces != null) {
		for (TypeReference typeReference : td.superInterfaces) {
			addFirstToken(usedNames, typeReference);
		}
	}

	return usedNames;
}

private void addFirstToken(java.util.Set<String> usedNames, TypeReference type) {
	if (type == null) 
		return;
	// Add the first token, because only that can collide.
	char[][] typeName = type.getTypeName();
	if (typeName != null && typeName.length >= 1)
		usedNames.add(String.valueOf(typeName[0]));
}

private String generateNonclashingNameFor(String classGenericName, java.util.Set<String> typeParamStrings) {
	if (!typeParamStrings.contains(classGenericName)) return classGenericName;
	int counter = 2;
	while (typeParamStrings.contains(classGenericName + counter)) counter++;
	return classGenericName + counter;
}

private TypeReference[] appendBuilderTypeReferences(TypeParameter[] typeParams, String classGenericName, String builderGenericName) {
	TypeReference[] typeReferencesToAppend = new TypeReference[2];
	typeReferencesToAppend[typeReferencesToAppend.length - 2] = new SingleTypeReference(classGenericName.toCharArray(), 0); 
	typeReferencesToAppend[typeReferencesToAppend.length - 1] = new SingleTypeReference(builderGenericName.toCharArray(), 0);
	return mergeToTypeReferences(typeParams, typeReferencesToAppend);
}

private TypeReference[] getTypeParametersFrom(TypeReference typeRef) {
	TypeReference[][] typeArgss = null;
	if (typeRef instanceof ParameterizedQualifiedTypeReference) {
		typeArgss = ((ParameterizedQualifiedTypeReference) typeRef).typeArguments;
	} else if (typeRef instanceof ParameterizedSingleTypeReference) {
		typeArgss = new TypeReference[][] {((ParameterizedSingleTypeReference) typeRef).typeArguments};
	}
	TypeReference[] typeArgs = new TypeReference[0];
	if (typeArgss != null && typeArgss.length > 0) {
		typeArgs = typeArgss[typeArgss.length - 1];
	}
	return typeArgs;
}

private static TypeReference createTypeReferenceWithTypeParameters(EclipseNode parent, String referenceName, TypeParameter[] typeParams) {
	if (typeParams.length > 0) {
		TypeReference[] typerefs = new TypeReference[typeParams.length];
		for (int i = 0; i < typeParams.length; i++) {
			typerefs[i] = new SingleTypeReference(typeParams[i].name, 0);
		}
		return generateParameterizedTypeReference(parent, referenceName.toCharArray(), false, typerefs, 0);
	} else {
		return generateTypeReference(parent, referenceName.toCharArray(), false, 0);
	}
}

private java.util.HashSet<String> gatherUsedTypeNames(List<JCTypeParameter> typeParams, JCClassDecl td) {
	java.util.HashSet<String> usedNames = new HashSet<String>();

	// 1. Add type parameter names.
	for (JCTypeParameter typeParam : typeParams)
		usedNames.add(typeParam.getName().toString());

	// 2. Add class name.
	usedNames.add(td.name.toString());

	// 3. Add used type names.
	for (JCTree member : td.getMembers()) {
		if (member.getKind() == com.sun.source.tree.Tree.Kind.VARIABLE && member instanceof JCVariableDecl) {
			JCTree type = ((JCVariableDecl)member).getType();
			if (type instanceof JCIdent)
				usedNames.add(((JCIdent)type).getName().toString());
		}
	}

	// 4. Add extends and implements clauses.
	addFirstToken(usedNames, Javac.getExtendsClause(td));
	for (JCExpression impl : td.getImplementsClause()) {
		addFirstToken(usedNames, impl);
	}

	return usedNames;
}

private void addFirstToken(java.util.Set<String> usedNames, JCTree type) {
	if (type == null) 
		return;
	if (type instanceof JCTypeApply) {
		type = ((JCTypeApply)type).clazz;
	}
	while (type instanceof JCFieldAccess && ((JCFieldAccess)type).selected != null) {
		// Add the first token, because only that can collide.
		type = ((JCFieldAccess)type).selected;
	}
	usedNames.add(type.toString());
}

private String generateNonclashingNameFor(String classGenericName, java.util.HashSet<String> typeParamStrings) {
	if (!typeParamStrings.contains(classGenericName)) return classGenericName;
	int counter = 2;
	while (typeParamStrings.contains(classGenericName + counter)) counter++;
	return classGenericName + counter;
}

private JavacNode findInnerClass(JavacNode parent, String name) {
	for (JavacNode child : parent.down()) {
		if (child.getKind() != Kind.TYPE) continue;
		JCClassDecl td = (JCClassDecl) child.get();
		if (td.name.contentEquals(name)) return child;
	}
	return null;
}

private ListBuffer<JCExpression> getTypeParamExpressions(List<? extends JCTree> typeParams, JavacTreeMaker maker, JavacNode source) {
	ListBuffer<JCExpression> typeParamsForBuilderParameter = new ListBuffer<JCExpression>();
	for (JCTree typeParam : typeParams) {
		if (typeParam instanceof JCTypeParameter) {
			typeParamsForBuilderParameter.append(maker.Ident(((JCTypeParameter)typeParam).getName()));
		} else if (typeParam instanceof JCIdent) {
			typeParamsForBuilderParameter.append(maker.Ident(((JCIdent)typeParam).getName()));
		} else if (typeParam instanceof JCFieldAccess) {
			typeParamsForBuilderParameter.append(copySelect(maker, (JCFieldAccess) typeParam));
		} else if (typeParam instanceof JCTypeApply) {
			typeParamsForBuilderParameter.append(cloneType(maker, (JCTypeApply)typeParam, source));
		}
	}
	return typeParamsForBuilderParameter;
}

private JCMethodDecl generateBuilderMethod(SuperBuilderJob job) {
	JavacTreeMaker maker = job.getTreeMaker();

	JCExpression call = maker.NewClass(null, List.<JCExpression>nil(), namePlusTypeParamsToTypeReference(maker, job.parentType, job.toName(job.builderImplClassName), false, job.typeParams), List.<JCExpression>nil(), null);
	JCStatement statement = maker.Return(call);

	JCBlock body = maker.Block(0, List.<JCStatement>of(statement));
	int modifiers = Flags.PUBLIC;
	modifiers |= Flags.STATIC;

	// Add any type params of the annotated class to the return type.
	ListBuffer<JCExpression> typeParameterNames = new ListBuffer<JCExpression>();
	typeParameterNames.appendList(typeParameterNames(maker, job.typeParams));
	// Now add the <?, ?>.
	JCWildcard wildcard = maker.Wildcard(maker.TypeBoundKind(BoundKind.UNBOUND), null);
	typeParameterNames.append(wildcard);
	wildcard = maker.Wildcard(maker.TypeBoundKind(BoundKind.UNBOUND), null);
	typeParameterNames.append(wildcard);
	// And return type annotations.
	List<JCAnnotation> annsOnParamType = List.nil();
	if (job.checkerFramework.generateUnique()) annsOnParamType = List.of(maker.Annotation(genTypeRef(job.parentType, CheckerFrameworkVersion.NAME__UNIQUE), List.<JCExpression>nil()));
	JCTypeApply returnType = maker.TypeApply(namePlusTypeParamsToTypeReference(maker, job.parentType, job.toName(job.builderAbstractClassName), false, List.<JCTypeParameter>nil(), annsOnParamType), typeParameterNames.toList());

	List<JCAnnotation> annsOnMethod = job.checkerFramework.generateSideEffectFree() ? List.of(maker.Annotation(genTypeRef(job.parentType, CheckerFrameworkVersion.NAME__SIDE_EFFECT_FREE), List.<JCExpression>nil())) : List.<JCAnnotation>nil();
	JCMethodDecl methodDef = maker.MethodDef(maker.Modifiers(modifiers, annsOnMethod), job.toName(job.builderMethodName), returnType, copyTypeParams(job.sourceNode, job.typeParams), List.<JCVariableDecl>nil(), List.<JCExpression>nil(), body, null);
	createRelevantNonNullAnnotation(job.parentType, methodDef);
	return methodDef;
}

/**
 * Handles the {@code lombok.Cleanup} annotation for eclipse.
 */
@Provides
public class HandleHelper extends EclipseAnnotationHandler<Helper> {
	private Statement[] getStatementsFromAstNode(ASTNode node) {
		if (node instanceof Block) return ((Block) node).statements;
		if (node instanceof AbstractMethodDeclaration) return ((AbstractMethodDeclaration) node).statements;
		if (node instanceof SwitchStatement) return ((SwitchStatement) node).statements;
		return null;
	}

	private void setStatementsOfAstNode(ASTNode node, Statement[] statements) {
		if (node instanceof Block) ((Block) node).statements = statements;
		else if (node instanceof AbstractMethodDeclaration) ((AbstractMethodDeclaration) node).statements = statements;
		else if (node instanceof SwitchStatement) ((SwitchStatement) node).statements = statements;
		else throw new IllegalArgumentException("Can't set statements on node type: " + node.getClass());
	}

	@Override public void handle(AnnotationValues<Helper> annotation, Annotation ast, EclipseNode annotationNode) {
		handleExperimentalFlagUsage(annotationNode, ConfigurationKeys.HELPER_FLAG_USAGE, "@Helper");

		EclipseNode annotatedType = annotationNode.up();
		EclipseNode containingBlock = annotatedType == null ? null : annotatedType.directUp();
		Statement[] origStatements = getStatementsFromAstNode(containingBlock == null ? null : containingBlock.get());

		if (annotatedType == null || annotatedType.getKind() != Kind.TYPE || origStatements == null) {
			annotationNode.addError("@Helper is legal only on method-local classes.");
			return;
		}

		TypeDeclaration annotatedType_ = (TypeDeclaration) annotatedType.get();
		int indexOfType = -1;
		for (int i = 0; i < origStatements.length; i++) {
			if (origStatements[i] == annotatedType_) {
				indexOfType = i;
				break;
			}
		}

		final List<String> knownMethodNames = new ArrayList<String>();

		for (AbstractMethodDeclaration methodOfHelper : annotatedType_.methods) {
			if (!(methodOfHelper instanceof MethodDeclaration)) continue;
			char[] name = methodOfHelper.selector;
			if (name != null && name.length > 0 && name[0] != '<') knownMethodNames.add(new String(name));
		}

		Collections.sort(knownMethodNames);
		final String[] knownMethodNames_ = knownMethodNames.toArray(new String[0]);

		final char[] helperName = new char[annotatedType_.name.length + 1];
		final boolean[] helperUsed = new boolean[1];
		helperName[0] = '$';
		System.arraycopy(annotatedType_.name, 0, helperName, 1, helperName.length - 1);

		ASTVisitor visitor = new ASTVisitor() {
			@Override public boolean visit(MessageSend messageSend, BlockScope scope) {
				if (messageSend.receiver instanceof ThisReference) {
					if ((((ThisReference) messageSend.receiver).bits & ASTNode.IsImplicitThis) == 0) return true;
				} else if (messageSend.receiver != null) return true;

				char[] name = messageSend.selector;
				if (name == null || name.length == 0 || name[0] == '<') return true;
				String n = new String(name);
				if (Arrays.binarySearch(knownMethodNames_, n) < 0) return true;
				messageSend.receiver = new SingleNameReference(helperName, messageSend.nameSourcePosition);
				helperUsed[0] = true;
				return true;
			}
		};

		for (int i = indexOfType + 1; i < origStatements.length; i++) {
			origStatements[i].traverse(visitor, null);
		}

		if (!helperUsed[0]) {
			annotationNode.addWarning("No methods of this helper class are ever used.");
			return;
		}

		Statement[] newStatements = new Statement[origStatements.length + 1];
		System.arraycopy(origStatements, 0, newStatements, 0, indexOfType + 1);
		System.arraycopy(origStatements, indexOfType + 1, newStatements, indexOfType + 2, origStatements.length - indexOfType - 1);
		LocalDeclaration decl = new LocalDeclaration(helperName, 0, 0);
		decl.modifiers |= ClassFileConstants.AccFinal;
		AllocationExpression alloc = new AllocationExpression();
		alloc.type = new SingleTypeReference(annotatedType_.name, 0L);
		decl.initialization = alloc;
		decl.type = new SingleTypeReference(annotatedType_.name, 0L);
		SetGeneratedByVisitor sgbvVisitor = new SetGeneratedByVisitor(annotationNode.get());
		decl.traverse(sgbvVisitor, null);
		newStatements[indexOfType + 1] = decl;
		setStatementsOfAstNode(containingBlock.get(), newStatements);
	}
}

@Provides
public class HandleHelper extends JavacAnnotationHandler<Helper> {
	private List<JCStatement> getStatementsFromJcNode(JCTree tree) {
		if (tree instanceof JCBlock) return ((JCBlock) tree).stats;
		if (tree instanceof JCCase) return ((JCCase) tree).stats;
		return null;
	}

	private void setStatementsOfJcNode(JCTree tree, List<JCStatement> statements) {
		if (tree instanceof JCBlock) ((JCBlock) tree).stats = statements;
		else if (tree instanceof JCCase) ((JCCase) tree).stats = statements;
		else throw new IllegalArgumentException("Can't set statements on node type: " + tree.getClass());
	}

	@Override public void handle(AnnotationValues<Helper> annotation, JCAnnotation ast, final JavacNode annotationNode) {
		handleExperimentalFlagUsage(annotationNode, ConfigurationKeys.HELPER_FLAG_USAGE, "@Helper");

		deleteAnnotationIfNeccessary(annotationNode, Helper.class);
		JavacNode annotatedType = annotationNode.up();
		JavacNode containingBlock = annotatedType == null ? null : annotatedType.directUp();
		List<JCStatement> origStatements = getStatementsFromJcNode(containingBlock == null ? null : containingBlock.get());

		if (annotatedType == null || annotatedType.getKind() != Kind.TYPE || origStatements == null) {
			annotationNode.addError("@Helper is legal only on method-local classes.");
			return;
		}

		JCClassDecl annotatedType_ = (JCClassDecl) annotatedType.get();
		Iterator<JCStatement> it = origStatements.iterator();
		while (it.hasNext()) {
			if (it.next() == annotatedType_) {
				break;
			}
		}

		java.util.List<String> knownMethodNames = new ArrayList<String>();

		for (JavacNode ch : annotatedType.down()) {
			if (ch.getKind() != Kind.METHOD) continue;
			String n = ch.getName();
			if (n == null || n.isEmpty() || n.charAt(0) == '<') continue;
			knownMethodNames.add(n);
		}

		Collections.sort(knownMethodNames);
		final String[] knownMethodNames_ = knownMethodNames.toArray(new String[0]);

		final Name helperName = annotationNode.toName("$" + annotatedType_.name);
		final boolean[] helperUsed = new boolean[1];
		final JavacTreeMaker maker = annotationNode.getTreeMaker();

		TreeVisitor<Void, Void> visitor = new TreeScanner<Void, Void>() {
			@Override public Void visitMethodInvocation(MethodInvocationTree node, Void p) {
				JCMethodInvocation jcmi = (JCMethodInvocation) node;
				apply(jcmi);
				return super.visitMethodInvocation(node, p);
			}

			private void apply(JCMethodInvocation jcmi) {
				if (!(jcmi.meth instanceof JCIdent)) return;
				JCIdent jci = (JCIdent) jcmi.meth;
				if (Arrays.binarySearch(knownMethodNames_, jci.name.toString()) < 0) return;
				jcmi.meth = maker.Select(maker.Ident(helperName), jci.name);
				recursiveSetGeneratedBy(jcmi.meth, annotationNode);
				helperUsed[0] = true;
			}
		};

		while (it.hasNext()) {
			JCStatement stat = it.next();
			stat.accept(visitor, null);
		}

		if (!helperUsed[0]) {
			annotationNode.addWarning("No methods of this helper class are ever used.");
			return;
		}

		ListBuffer<JCStatement> newStatements = new ListBuffer<JCStatement>();

		boolean mark = false;
		for (JCStatement stat : origStatements) {
			newStatements.append(stat);
			if (mark || stat != annotatedType_) continue;
			mark = true;
			JCExpression init = maker.NewClass(null, List.<JCExpression>nil(), maker.Ident(annotatedType_.name), List.<JCExpression>nil(), null);
			JCExpression varType = maker.Ident(annotatedType_.name);
			JCVariableDecl decl = maker.VarDef(maker.Modifiers(Flags.FINAL), helperName, varType, init);
			recursiveSetGeneratedBy(decl, annotationNode);
			newStatements.append(decl);
		}
		setStatementsOfJcNode(containingBlock.get(), newStatements.toList());
	}
}

/**
 * Handles the {@code lombok.Cleanup} annotation for javac.
 */
@Provides
public class HandleCleanup extends JavacAnnotationHandler<Cleanup> {
	@Override public void handle(AnnotationValues<Cleanup> annotation, JCAnnotation ast, JavacNode annotationNode) {
		handleFlagUsage(annotationNode, ConfigurationKeys.CLEANUP_FLAG_USAGE, "@Cleanup");

		if (inNetbeansEditor(annotationNode)) return;

		deleteAnnotationIfNeccessary(annotationNode, Cleanup.class);
		String cleanupName = annotation.getInstance().value();
		if (cleanupName.length() == 0) {
			annotationNode.addError("cleanupName cannot be the empty string.");
			return;
		}

		if (annotationNode.up().getKind() != Kind.LOCAL) {
			annotationNode.addError("@Cleanup is legal only on local variable declarations.");
			return;
		}

		JCVariableDecl decl = (JCVariableDecl)annotationNode.up().get();

		if (decl.init == null) {
			annotationNode.addError("@Cleanup variable declarations need to be initialized.");
			return;
		}

		JavacNode ancestor = annotationNode.up().directUp();
		JCTree blockNode = ancestor.get();

		final List<JCStatement> statements;
		if (blockNode instanceof JCBlock) {
			statements = ((JCBlock)blockNode).stats;
		} else if (blockNode instanceof JCCase) {
			statements = ((JCCase)blockNode).stats;
		} else if (blockNode instanceof JCMethodDecl) {
			statements = ((JCMethodDecl)blockNode).body.stats;
		} else {
			annotationNode.addError("@Cleanup is legal only on a local variable declaration inside a block.");
			return;
		}

		boolean seenDeclaration = false;
		ListBuffer<JCStatement> newStatements = new ListBuffer<JCStatement>();
		ListBuffer<JCStatement> tryBlock = new ListBuffer<JCStatement>();
		for (JCStatement statement : statements) {
			if (!seenDeclaration) {
				if (statement == decl) seenDeclaration = true;
				newStatements.append(statement);
			} else {
				tryBlock.append(statement);
			}
		}

		if (!seenDeclaration) {
			annotationNode.addError("LOMBOK BUG: Can't find this local variable declaration inside its parent.");
			return;
		}
		doAssignmentCheck(annotationNode, tryBlock.toList(), decl.name);

		JavacTreeMaker maker = annotationNode.getTreeMaker();
		JCFieldAccess cleanupMethod = maker.Select(maker.Ident(decl.name), annotationNode.toName(cleanupName));
		List<JCStatement> cleanupCall = List.<JCStatement>of(maker.Exec(
				maker.Apply(List.<JCExpression>nil(), cleanupMethod, List.<JCExpression>nil())));

		JCExpression preventNullAnalysis = preventNullAnalysis(maker, annotationNode, maker.Ident(decl.name));
		JCBinary isNull = maker.Binary(CTC_NOT_EQUAL, preventNullAnalysis, maker.Literal(CTC_BOT, null));

		JCIf ifNotNullCleanup = maker.If(isNull, maker.Block(0, cleanupCall), null);

		JCBlock finalizer = recursiveSetGeneratedBy(maker.Block(0, List.<JCStatement>of(ifNotNullCleanup)), annotationNode);

		newStatements.append(setGeneratedBy(maker.Try(setGeneratedBy(maker.Block(0, tryBlock.toList()), annotationNode), List.<JCCatch>nil(), finalizer), annotationNode));

		if (blockNode instanceof JCBlock) {
			((JCBlock)blockNode).stats = newStatements.toList();
		} else if (blockNode instanceof JCCase) {
			((JCCase)blockNode).stats = newStatements.toList();
		} else if (blockNode instanceof JCMethodDecl) {
			((JCMethodDecl)blockNode).body.stats = newStatements.toList();
		} else throw new AssertionError("Should not get here");

		ancestor.rebuild();
	}

	public JCExpression preventNullAnalysis(JavacTreeMaker maker, JavacNode node, JCExpression expression) {
		if (LombokOptionsFactory.getDelombokOptions(node.getContext()).getFormatPreferences().danceAroundIdeChecks()) {
			JCMethodInvocation singletonList = maker.Apply(List.<JCExpression>nil(), chainDotsString(node, "java.util.Collections.singletonList"), List.of(expression));
			JCMethodInvocation cleanedExpr = maker.Apply(List.<JCExpression>nil(), maker.Select(singletonList, node.toName("get")) , List.<JCExpression>of(maker.Literal(CTC_INT, 0)));
			return cleanedExpr;
		} else {
			return expression;
		}
	}

	public void doAssignmentCheck(JavacNode node, List<JCStatement> statements, Name name) {
		for (JCStatement statement : statements) doAssignmentCheck0(node, statement, name);
	}

	public void doAssignmentCheck0(JavacNode node, JCTree statement, Name name) {
		if (statement instanceof JCAssign) doAssignmentCheck0(node, ((JCAssign)statement).rhs, name);
		if (statement instanceof JCExpressionStatement) doAssignmentCheck0(node,
				((JCExpressionStatement)statement).expr, name);
		if (statement instanceof JCVariableDecl) doAssignmentCheck0(node, ((JCVariableDecl)statement).init, name);
		if (statement instanceof JCTypeCast) doAssignmentCheck0(node, ((JCTypeCast)statement).expr, name);
		if (statement instanceof JCIdent) {
			if (((JCIdent)statement).name.contentEquals(name)) {
				JavacNode problemNode = node.getNodeFor(statement);
				if (problemNode != null) problemNode.addWarning(
				"You're assigning an auto-cleanup variable to something else. This is a bad idea.");
			}
		}
	}
}

/**
 * Return the name of your type (simple name), method, field, or local variable. Return null if this
 * node doesn't really have a name, such as initializers, while statements, etc.
 */
public abstract String getName();

/** Returns the structurally significant node that encloses this one.
 * 
 * @see #isStructurallySignificant()
 */
public L up() {
	L result = parent;
	while (result != null && !result.isStructurallySignificant) result = result.parent;
	return result;
}

/**
 * {@code @Foo int x, y;} is stored in both javac and ecj as 2 FieldDeclarations, both with the same annotation as child.
 * The normal {@code up()} method can't handle having multiple parents, but this one can.
 */
public Collection<L> upFromAnnotationToFields() {
	if (getKind() != Kind.ANNOTATION) return Collections.emptyList();
	L field = up();
	if (field == null || field.getKind() != Kind.FIELD) return Collections.emptyList();
	L type = field.up();
	if (type == null || type.getKind() != Kind.TYPE) return Collections.emptyList();

	List<L> fields = new ArrayList<L>();
	for (L potentialField : type.down()) {
		if (potentialField.getKind() != Kind.FIELD) continue;
		for (L child : potentialField.down()) {
			if (child.getKind() != Kind.ANNOTATION) continue;
			if (child.get() == get()) fields.add(potentialField);
		}
	}

	return fields;
}

